(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["coding"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-context-aware-codellm-eviction-for-a-2025"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-1\">一 · 现场：一个仓库级补全请求如何把显存吃满</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-2\">二 · 旧方案：LRU 与固定窗口的两种时间序假设</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-3\">三 · 失效机制：为什么重算会打穿低延迟 SLO</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-4\">四 · 打分替代时间序：一个可部署的机制骨架</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-5\">五 · 与既有栈的耦合点：驱逐不是孤立策略</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-6\">六 · 驱逐策略的失效边界与隐性账本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-7\">七 · 请求形态先于策略：三类流量在同一服务里互相挤压</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-8\">八 · 并发与批大小：预算约束下的可行域是二维的</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-9\">九 · SLO 的形状：首token延迟分位而非均值主导设计</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-10\">十 · 长尾：被逐出块的依赖链长度决定尾部厚度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-11\">十一 · 方案反过来限制负载：驱逐策略塑造了请求的可接受形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-12\">十二 · 可核查的测量清单与Blackwell档位的对应</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-13\">十三 · 从驱逐分数到 kernel 选择：为什么数值精度是驱逐策略的隐藏变量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-14\">十四 · 核心 kernel 的数据通路：QK^T 与 PV 两段的精度分工</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-15\">十五 · 累加精度与误差传播：驱逐后重算的数值一致性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-16\">十六 · Blackwell 特性如何改变驱逐的经济性：tcgen05、TMEM、2-SM MMA</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-17\">十七 · 逐出决策与 kernel 执行的时序耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-18\">十八 · 精度档位下的驱逐参数与可观测项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-19\">十九 · 语义打分的开销边界与失效条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-20\">二十 · 显存账本的三层结构与可复算预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-21\">二十一 · 分页与块索引：驱逐的物理单位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-22\">二十二 · 压缩、复用与卸载：三条扩容路径的代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-23\">二十三 · 带宽瓶颈的定位：decode是带宽活，驱逐是延迟活</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-24\">二十四 · 一个可复算的部署预算例</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-25\">二十五 · 冷启动与索引开销：预算账本外的隐项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-26\">二十六 · 驱逐策略的边界：打分开销、冷启动与跨文件解析的代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-27\">二十七 · 驱逐决策嵌入连续批处理循环的位置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-28\">二十八 · Chunked prefill 与驱逐预算的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-29\">二十九 · 优先级、抢占与尾延迟的压制路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-30\">三十 · 分离式预填/解码下的驱逐归属</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-31\">三十一 · 时延与吞吐的取舍判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-32\">三十二 · 监控闭环与打分权重的在线调整</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-33\">三十三 · 驱逐决策落在哪个并行维度上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-34\">三十四 · NVLink 5 与 NVSwitch：什么时候通信不痛</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-35\">三十五 · All-to-All 与 EP：驱逐与路由的耦合点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-36\">三十六 · NIXL 传输与分离式预填/解码的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-37\">三十七 · 通信成为瓶颈的判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-38\">三十八 · 驱逐决策与并行切分的耦合边界：通信何时压过命中收益</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-39\">三十九 · 驱逐决策落在通信拓扑上的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-40\">四十 · 精度塌陷：从逐出到数值的连锁反应</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-41\">四十一 · OOM：预算压力下的驱逐时序错位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-42\">四十二 · 批抖动与尾延迟：驱逐打断批内一致性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-43\">四十三 · 静默降级：命中率正常但语义命中失败</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-44\">四十四 · 监控面与回滚：把打分权重当作可回退配置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-45\">四十五 · 失效边界：打分收益被自身开销吃掉的那一刻</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-46\">四十六 · 口径先于数字：这篇论文能给出什么、不能给出什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-47\">四十七 · 硬件档位：KV 预算的分母必须先钉死</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-48\">四十八 · batch 与并发：驱逐收益与批调度的耦合口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-49\">四十九 · 指标族：五个量各自回答不同问题，不可互相替代</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-50\">五十 · 哪些提升不可比：四类失效比较</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-51\">五十一 · 复现清单：把不可核验的部分变成可核验的</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-52\">五十二 · 基准口径的失效边界：打分开销、冷启动与不可比的“提升”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-53\">五十三 · 迁移到非代码模型：信号源先塌一半</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-54\">五十四 · 迁移到别的代码模型：切块粒度与 tokenizer 必须重标定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-55\">五十五 · 与量化 KV 结合时的边界：分数不能替代精度决策</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-56\">五十六 · 规模上限：依赖图与索引是 O(仓库规模) 的隐性成本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-57\">五十七 · 不适用的场景：冷启动、短会话、单文件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-58\">五十八 · 迁移检查清单：改什么、测什么、什么时候放弃</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-59\">五十九 · 迁移边界：打分器在什么仓库、什么模型上会失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-context-aware-codellm-eviction-for-a-2025-sec-60\">六十 · 迁移边界：依赖图假设、冷启动失效与规模上限</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:551px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 551.0 423\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"469.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">请求到达后对上下文做分块并检索前缀缓存，得到候选复用块集合。</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"469.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">对候选块计算上下文感知分数，融合引用关系、会话阶段与近期复用频次。</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"469.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">在KV预算约束下按分数排序，低分块进入逐出候选队列。</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"469.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">批调度前执行逐出与重算规划，保证解码过程中不再触发逐出。</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"469.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">解码阶段复用保留块，未命中部分重算并回填索引。</text><line x1=\"82.0\" y1=\"342.2\" x2=\"82.0\" y2=\"359.2\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 358.2 L 86.5 358.2 L 82.0 366.2 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"366.2\" width=\"469.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"388.7\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"392.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">6</text><text x=\"75.0\" y=\"393.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">监控命中率与首token延迟，反馈调整打分权重与保留窗口。</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-1\">一 · 现场：一个仓库级补全请求如何把显存吃满</h3>\n<p>设想一个在线编码助手：IDE 插件把当前文件、光标附近若干行、被打开过的其他文件片段、以及本轮会话里前几次问答的上下文，一起打包成一次仓库级补全请求，打到推理服务。请求不是孤立的——同一个开发者在一个会话里连续改十几个文件，每个请求都带着上一轮的对话历史与代码上下文。服务侧为了省掉重复预填，开启了前缀缓存：相同前缀的 KV 块直接复用，只对新增后缀做 prefill。这套机制在短会话里工作得很好，命中率高、首 token 延迟稳定。</p>\n<p>问题出在长会话与跨文件编辑上。KV cache 的占用不是按“请求”算的，而是按“驻留块”算的：每个被缓存的前缀块都占着一份 KV，块数随会话长度和文件数线性增长。Blackwell 档位下，单卡 HBM 容量是硬约束，KV 预算一旦被历史块占满，新请求要么排队等逐出，要么被迫降低批大小。更糟的是，仓库级上下文里大量块是“结构性冗余”的——一个类型定义被五个文件引用，一段工具函数被后续补全反复需要，但它们的访问时间戳可能很旧。纯时间序驱逐在这里直接失效。</p>\n<p>这就是论文要处理的现场：不是“缓存不够大”，而是“缓存里放错了东西”。显存容量成为并发与延迟的主要瓶颈，而驱逐策略决定了哪些块值得留下。下面把旧方案的做法、代价和失效点拆开看。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-2\">二 · 旧方案：LRU 与固定窗口的两种时间序假设</h3>\n<p>推理栈里最常见的 KV 驱逐基线是 LRU：为每个缓存块维护最近访问时间，预算压力下逐出最久未用的块。它的隐含假设是“最近用过的还会再用”，这在通用文本对话里大致成立，因为话题局部性强。但在代码场景里，这个假设被两类访问模式打破。第一类是跨文件符号引用：一个 <code>struct</code> 或接口定义可能在会话早期被读入，之后二十分钟没被直接命中，但当前编辑位置一旦落到调用它的函数里，这个块立刻变成高价值块——LRU 已经把它逐出了。第二类是阶段性切换：agent 循环里“读仓库—改代码—跑测试—修错误”四个阶段对上下文的需求完全不同，上一阶段频繁命中的块在下一阶段可能整体失效，而 LRU 没有任何阶段信号。</p>\n<p>固定窗口是另一种常见做法：只保留最近 N 个块或最近 M 个 token 的上下文，超出部分直接丢弃。它比 LRU 更可预测，显存上界好算，但代价是把“窗口外的仍被引用块”一刀切掉。窗口大小本身是个两难：调大，显存吃紧、批大小下降、吞吐掉；调小，跨文件依赖被截断，补全质量与命中率同时下降。两种基线共享同一个缺陷——驱逐信号只有时间，没有语义。</p>\n<p>把代价量化一下。设缓存块总数为 <code>B</code>，单块 KV 字节数为 <code>k</code>，则驻留显存为 <code>B·k</code>；在固定 HBM 预算 <code>M</code> 下，可驻留块数上界是 <code>⌊M/k⌋</code>。批大小 <code>b</code> 与每请求平均活跃块数 <code>n</code> 共同决定并发上限，粗略地有 <code>b·n·k ≤ M</code>。驱逐策略不改变 <code>k</code>，但它改变“有效命中块数”——被错误逐出的块要在解码时重算，重算的 prefill 计算量与 token 数成正比，直接体现在首 token 延迟上。LRU 在跨文件场景下的错误逐出率越高，重算 token 数越大，首 token 延迟分位越抖。这就是“非改不可”的量化理由：不是显存不够，是同样的显存预算下，时间序策略把预算浪费在了不会再被引用的块上，同时把仍被引用的块踢了出去。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-3\">三 · 失效机制：为什么重算会打穿低延迟 SLO</h3>\n<p>重算的代价不只是算力。一个被逐出的块如果在解码中途被需要，服务要么停下来重新 prefill 这个块再继续解码，要么让该请求等待下一轮批调度。前者打断整个批内其他请求的解码节奏——连续批处理里，一个请求的停顿会拖累同批所有请求的 token 间隔；后者把延迟从“一次 prefill”放大成“排队 + 一次 prefill”。两种路径都会在首 token 延迟分位上留下尖刺，而在线编码助手恰恰是对首 token 延迟最敏感的场景：开发者在光标处等补全，几百毫秒的抖动就能感知到。</p>\n<p>更隐蔽的代价是重算引发的连锁。重算块回填索引后，缓存占用瞬间上升，可能触发下一轮驱逐；如果驱逐仍按时间序，刚回填的块时间戳最新不会被踢，但被它挤掉的可能是另一个高依赖块。这种“逐出—重算—再逐出”的循环在长会话里会自我强化，表现为命中率随会话时长缓慢下滑，而不是稳定在一个水平。监控上看到的是重算 token 数持续偏高、缓存冷启动命中率低、逐出次数频繁，但单看某一时刻的显存占用并不紧张——这正是纯时间序策略的诊断特征。</p>\n<p>论文的切入点就在这里：驱逐决策必须发生在批形成之前，而不是解码中途。把逐出前移，意味着批调度器在组批时就已经知道哪些块会被保留、哪些请求需要重算，重算被规划进 prefill 阶段而不是打断 decode。这个顺序调整本身不减少重算量，但它把抖动的来源从“解码中断”转移到“可预期的 prefill 增量”，对首 token 延迟分位的改善是结构性的。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-4\">四 · 打分替代时间序：一个可部署的机制骨架</h3>\n<p>论文用上下文感知分数替代访问时间戳。每个 KV 块 <code>b</code> 的分数由四项构成：近期复用概率 <code>R(b)</code>、结构依赖度 <code>D(b)</code>、会话阶段适配度 <code>F(b)</code>、以及逐出与重算成本 <code>C(b)</code>。形式化为：</p>\n<div class=\"formula\">$$S(b)=\\alpha\\cdot R(b)+\\beta\\cdot D(b)+\\gamma\\cdot F(b)-\\delta\\cdot C(b)$$</div>\n<p>四项的信号来源不同。<code>R(b)</code> 来自前缀缓存的命中历史，是时间序信息的软化版本；<code>D(b)</code> 来自跨文件引用关系——一个块被多少当前编辑位置的符号引用、是否处于调用链上游，这类信息需要服务侧维护分块 KV 索引与依赖图；<code>F(b)</code> 编码会话阶段，比如“改代码”阶段偏向保留被编辑文件的邻接块，“跑测试”阶段偏向保留测试相关符号；<code>C(b)</code> 是重算代价的估计，块越大、依赖越深，逐出它未来重算越贵，因此作为惩罚项。材料未给出各权重取值与归一化方式，权重属于部署期在线调参，依据线上命中率与首 token 延迟分位反馈更新，而非梯度训练。</p>\n<p>工程上关键的一步是顺序：请求进入时先做前缀匹配得到候选复用块，再对候选块打分，然后在批调度前按预算逐出低分块并规划重算。逐出发生在组批阶段，解码过程中不再触发逐出。伪代码思路是：<code>candidates = prefix_match(req)</code>；<code>scores = score(candidates, dep_graph, phase)</code>；<code>evict(lowest(scores), until budget_ok)</code>；<code>batch = schedule(req, retained_blocks)</code>；<code>decode(batch)</code>。这个顺序把驱逐从“解码路径上的异常分支”变成“调度路径上的常规步骤”，是整篇论文最可直接落地的工程判断。</p>\n<p>代价也要摆明。依赖图构建与打分本身消耗 CPU 与索引内存，跨文件依赖解析在超大仓库下的可扩展性材料未给出。如果打分开销接近甚至超过命中收益，这套机制就是负收益——这是论文自己列出的失败模式之一。在 Blackwell 部署档位上，KV 若采用 NVFP4/FP8 量化，单块字节数 <code>k</code> 下降，可驻留块数上升，打分的边际收益会被稀释：块多了，逐出压力小了，但依赖图规模也大了。打分收益与开销的平衡点必须在具体档位上实测，材料未给出硬件档位、批大小与并发配置，因此无法核验其 SLO 达成情况。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-5\">五 · 与既有栈的耦合点：驱逐不是孤立策略</h3>\n<p>把驱逐放回推理栈看，它至少与三个子系统耦合。第一是前缀缓存：驱逐依赖前缀匹配的质量，缓存冷启动阶段命中率低，驱逐策略收益有限，需与预填策略协同评估。第二是批调度与连续批处理：逐出前移到组批前，意味着调度器要能接受“部分请求带重算增量”的批，重算 token 数成为组批时的一个约束维度，而不是事后补救。第三是量化与并行：KV 量化改变 <code>k</code>，分离式预填/解码改变重算发生的位置——如果 prefill 与 decode 在不同资源池，逐出决策还要考虑跨池传输成本，材料未涉及这一层。</p>\n<p>与 LRU 和固定窗口的对比，论文主张在长会话跨文件场景减少重算，但未给出可核验数字。可推断的消融维度是打分项（引用、阶段、复用频次）的取舍，具体结果未给出。这意味着读者不能把“上下文感知”当作免费收益：它是一套用 CPU 与索引开销换命中率的交易，交易是否划算取决于仓库规模、会话长度分布与 SLO 严格程度。在一个短会话、单文件为主的负载里，LRU 的时间序假设基本成立，打分机制的增量收益接近于零，而开销是实打实的。</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>LRU / 固定窗口</th><th>上下文感知驱逐</th></tr></thead><tbody><tr><td>驱逐信号</td><td>访问时间 / 窗口位置</td><td>复用概率 + 结构依赖 + 会话阶段 − 重算成本</td></tr><tr><td>逐出时机</td><td>可在解码路径触发</td><td>前移到批调度之前</td></tr><tr><td>主要代价</td><td>错误逐出导致重算与延迟抖动</td><td>依赖图构建与打分的 CPU/索引开销</td></tr><tr><td>失效场景</td><td>跨文件引用、阶段切换</td><td>缓存冷启动、超大仓库依赖解析、短会话</td></tr><tr><td>监控指标</td><td>命中率、显存占用</td><td>命中率、重算 token 数、首 token 延迟分位、逐出次数</td></tr></tbody></table>\n<p>这张表的意义在于把“换策略”还原成“换代价结构”：旧方案的代价藏在延迟抖动里，新方案的代价摆在 CPU 与索引上。工程判断不是选哪个更先进，而是看你的负载里跨文件引用密度和会话长度是否足以让命中收益覆盖打分开销。材料没有给出这个平衡点的数字，所以任何部署前的结论都只能来自本档位上的实测——这正是这套方法在 Blackwell 上落地时最先要回答的问题。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-6\">六 · 驱逐策略的失效边界与隐性账本</h3>\n<p>这套打分驱逐的收益并非无条件成立，它的第一个失效条件藏在缓存冷启动阶段。服务刚扩容或新仓库首次接入时，分块KV索引尚未积累足够的复用频次R(b)，依赖图D(b)也因跨文件符号未解析完整而稀疏，此时打分器退化到近似随机排序，甚至不如固定窗口稳定。冷启动期的命中率接近零，逐出与重算规划只是在制造额外索引开销：每个请求都要走前缀匹配、块切分、依赖查询三步，而这三步的CPU代价在命中率低时无法被摊薄。工程判断是：冷启动窗口内应退回保守的固定保留策略，待命中率越过阈值后再启用打分，否则驱逐逻辑本身成为首token延迟的抖动源。</p>\n<p>第二个边界是依赖图的可扩展性。仓库级上下文意味着依赖解析要跨文件、跨符号甚至跨模块，超大仓库下依赖图的构建与查询开销随块数增长，材料未给出该开销的量级，但可以确定它与命中收益之间存在一个平衡点。设单请求打分开销为 <span class=\"formula\">$$T_{score}=n_b\\cdot(c_{idx}+c_{dep})$$</span>，其中n_b为候选块数、c_idx为索引查询、c_dep为依赖查询的单块代价；当命中率h下降时，节省的重算token收益按(1−h)缩水，而T_score不变，于是净收益在某个h以下转负。这正是“把语义打分当作免费收益”的典型误判——打分不是零成本信号，它是用CPU与索引带宽换取重算token的交换。</p>\n<table class=\"mini\"><thead><tr><th>场景</th><th>命中率状态</th><th>主要代价</th><th>策略取向</th></tr></thead><tbody><tr><td>冷启动/新仓库</td><td>接近零</td><td>索引与依赖查询开销全额付出</td><td>退回固定保留窗口</td></tr><tr><td>稳态长会话</td><td>较高且稳定</td><td>打分开销被重算节省摊薄</td><td>启用上下文感知打分</td></tr><tr><td>超大仓库跨文件</td><td>依赖图稀疏</td><td>依赖解析可扩展性未验证</td><td>限制依赖图深度，按需解析</td></tr></tbody></table>\n<p>第三个失效条件是驱逐时机与批调度的耦合纪律。逐出必须严格前移到批形成之前，一旦在解码中途触发逐出，批内其他请求的KV被牵连重算，抖动会沿着整个批扩散，首token延迟分位直接恶化。这条纪律在实现上意味着驱逐决策不能由解码循环内的异步回调驱动，而必须作为批调度器的前置阶段串行执行，代价是调度器多了一个同步屏障，吞吐在高压下会因该屏障而略降。与NVFP4/FP8量化KV结合时，预算扩大使可保留块数上升，打分的边际收益反而下降——量化已经把显存瓶颈推远，驱逐策略的紧迫性随之减弱，此时更该关注的是量化KV的数值稳定性而非驱逐精度。因此这套方案的正确用法是：在未量化或轻度量化的显存档位下作为显存节流阀，在重度量化档位下退居次要，避免为已不紧张的预算付出打分开销。</p>\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-7\">七 · 请求形态先于策略：三类流量在同一服务里互相挤压</h3>\n<p>仓库级代码补全与agent循环在服务侧并不是一种请求，而是至少三种形态混跑：单次行内补全（输入是光标前后若干文件片段，输出十几个token）、跨文件符号级补全（输入含类型定义与调用点，输出中等长度）、以及agent循环中的多轮工具调用（每轮追加工具返回、错误栈、检索片段，轮数可达数十）。这三类请求的输入长度分布差异极大，且同一会话内长度单调增长——agent每轮把上一轮结果拼回上下文，KV块集合只增不减。驱逐策略面对的不是一个静态分布，而是一条随时间漂移的序列：会话早期块集合小、命中率高；会话后期块集合超出预算，驱逐开始频繁触发。</p>\n<p>测量口径必须把这三类分开统计，否则命中率会被行内补全的高基数稀释。可核查的做法是：按请求类型分桶记录输入token数、块数、命中块数、重算token数、首token延迟（TTFT）与端到端延迟，并保留分位而非均值。分桶维度至少包括请求类型、会话轮次区间、输入长度区间。均值在这里没有意义：TTFT的P99由agent循环后期的长上下文请求决定，而这类请求在总量中占比很低。</p>\n<p>负载对方案的第一个塑造是：驱逐必须按会话而非按请求做预算。若按单请求预算驱逐，同一会话的下一轮会重新拉回刚被逐出的块，形成抖动。第二个塑造是：行内补全的SLO最紧，但它对KV预算的占用最小，驱逐压力几乎全部来自agent循环。因此打分函数中的会话阶段项 γ·F(b) 实际上承担了区分这两类流量的职责——F(b) 在会话后期对“本轮工具返回引入的新块”给高分，对“早期已消费完的历史块”给低分。</p>\n<div class=\"formula\">$$\\text{TTFT}_{p99}=\\max_{r\\in\\text{agent轮次}}\\left(t_{\\text{prefill}}(r)+t_{\\text{evict}}(r)+t_{\\text{recompute}}(r)\\right)$$</div>\n<p>工程代价在于：驱逐与重算都发生在批形成前，它们的时间直接进入TTFT的关键路径。一次驱逐若涉及大量块的重算规划，prefill阶段的GPU占用会被拉长，挤占同批次其他请求的SM时间。具体例子：一个agent会话在第12轮引入了一个跨文件类型定义块，该块被后续5轮引用；若LRU在第13轮把它逐出，第14轮的补全请求需要重算该块及其依赖链，重算token数远超单块本身，TTFT分位出现尖峰。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-8\">八 · 并发与批大小：预算约束下的可行域是二维的</h3>\n<p>在Blackwell档位上，KV预算由显存容量与量化方案共同决定，而并发数×平均KV占用必须落在预算内。驱逐策略改变的是“平均KV占用”这个乘数：保留块越多，单请求占用越高，可支撑并发越低。这不是一个可以分别优化的两个变量，而是一条约束线。设单请求保留块数为 k、每块KV字节数为 s、并发为 n、可用KV预算为 M，则可行域为 n·k·s ≤ M。驱逐策略通过降低 k 的上界来提高 n，代价是重算概率上升。</p>\n<p>测量口径：必须同时记录并发数的时间序列与批大小的分布，而不是只报峰值并发。连续批处理下批大小是动态的，驱逐发生在批形成前意味着驱逐决策看到的是“本批候选请求集合”，而不是全局。若驱逐只看单请求预算，会出现同一批内多个请求争抢同一批可复用块的情况——这些块被一个请求保留、被另一个请求逐出，前缀缓存索引出现不一致。可核查的指标是“批内块冲突率”：同一批内被两个以上请求引用但只被部分请求保留的块占比。</p>\n<table class=\"mini\"><thead><tr><th>观测项</th><th>口径</th><th>对策略的约束</th></tr></thead><tbody><tr><td>并发数</td><td>按秒采样，报P50/P95，与批大小联合分布</td><td>决定KV预算的分配粒度</td></tr><tr><td>批大小</td><td>解码步级别的直方图</td><td>驱逐必须在批形成前完成，不能跨批延迟</td></tr><tr><td>批内块冲突率</td><td>批内共享块被部分保留的比例</td><td>要求驱逐决策具备批级视图</td></tr><tr><td>重算token数/请求</td><td>按请求类型分桶，报分位</td><td>直接进入TTFT关键路径</td></tr></tbody></table>\n<p>具体机制上，驱逐与批调度的耦合点在于：批调度器在选批时已经知道每个候选请求的块命中情况，若某请求命中率过低、重算量过大，调度器可以选择把它推迟到下一批，让高命中请求先跑。这实际上是用调度顺序换SLO——把长尾请求的重算代价从关键路径上挪开，代价是这部分请求的端到端延迟变长。工程判断是：当重算token数超过某请求自身输入token数的某个比例时，推迟比硬跑更划算，但这个比例必须由线上分位反馈确定，材料未给出取值。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-9\">九 · SLO 的形状：首token延迟分位而非均值主导设计</h3>\n<p>代码补全的SLO以TTFT分位为主，原因是行内补全的用户感知几乎全部落在首token上，后续token以流式返回。agent循环则不同，它的SLO更接近端到端轮次延迟，因为每轮之间还有工具执行。驱逐策略对这两类SLO的影响路径不同：对行内补全，驱逐造成的重算直接抬高TTFT；对agent循环，驱逐造成的重算抬高的是轮次延迟，且可能触发连锁——重算消耗的算力挤占下一轮的工具调用准备时间。</p>\n<p>可核查的测量口径是把TTFT分解为三段：前缀匹配与打分时间、驱逐与重算规划时间、实际prefill时间。三段分别报分位，才能判断驱逐开销是否抵消了命中收益。论文的失败模式之一正是“把语义依赖打分当作免费收益”，若打分与依赖图查询的CPU时间在P99上超过重算节省的GPU时间，净收益为负。具体例子：一个超大仓库的跨文件依赖图查询在请求进入时同步执行，若图规模导致查询延迟进入毫秒级，而命中节省的prefill只有同等量级，则TTFT分位不降反升。</p>\n<div class=\"formula\">$$\\text{净收益}=\\Delta t_{\\text{recompute}}\\cdot(1-h)-\\left(t_{\\text{score}}+t_{\\text{graph}}\\right)$$</div>\n<p>其中 h 为命中率。这个式子说明：命中率提升必须大到足以覆盖打分与图查询的固定开销，否则策略在低命中场景下是负优化。缓存冷启动阶段 h 接近零，此时驱逐策略的收益有限，应与预填策略协同——冷启动时优先扩大预填并行度而非精细驱逐。工程上可设一个开关：当会话轮次低于某阈值或命中率低于某阈值时，退化为固定窗口保留，避免打分开销白白付出。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-10\">十 · 长尾：被逐出块的依赖链长度决定尾部厚度</h3>\n<p>长尾的来源不是请求长度本身，而是被逐出块的依赖链长度。一个函数定义块被逐出后，引用它的调用点块在重算时必须先重建该定义，若该定义又依赖其他类型块，重算沿依赖图向上传播。依赖链越长，单次驱逐的尾部代价越大。这与LRU的失败模式直接对应：LRU只看访问时间，会把“访问时间早但被多处引用”的定义块逐出，而这类块恰恰是依赖链的根。</p>\n<p>测量口径：记录每次驱逐事件的“重算传播深度”与“重算token数”，按驱逐原因分桶（时间序逐出、预算压力逐出、阶段切换逐出）。可核查的长尾指标是“驱逐后首次未命中的TTFT增量”分布——它直接度量一次错误驱逐的代价。具体机制上，打分函数中的 D(b) 项（依赖度）应当以“该块被后续请求引用的概率×引用链长度”为输入，而非简单的入度计数；入度高的块未必会被后续补全引用，而处于当前编辑位置上游的块即使入度低也值得保留。</p>\n<p>工程代价：依赖图维护本身是长尾的一部分。超大仓库下跨文件依赖解析的可扩展性材料未给出，但可以判断其代价随仓库规模超线性增长的风险——符号解析需要处理宏、模板、条件编译，这些在C++类仓库中会使依赖图边数膨胀。可核查的做法是限制依赖图的作用域：只对当前会话触及的文件子图做解析，子图外的块退化为按复用频次打分。这把图查询的复杂度从仓库规模解耦到会话规模。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-11\">十一 · 方案反过来限制负载：驱逐策略塑造了请求的可接受形态</h3>\n<p>驱逐策略不是被动适应负载，它会反向筛选负载。当服务对长会话请求的TTFT分位无法保证时，前端会倾向于截断会话、拆分会话或限制单轮上下文注入量——这些是产品层对推理层约束的响应。反过来，若驱逐策略能把长会话的TTFT分位压住，前端就可以放宽单轮上下文注入，让agent拿到更多检索片段，提升补全质量。这是一个闭环：策略的SLO达成能力决定了负载形态的上界。</p>\n<p>可核查的测量口径是“会话长度-延迟弹性”：在同一策略下，人为把会话轮次上限从 N 提到 N+m，观察TTFT分位的变化斜率。斜率陡说明策略对长会话的支撑已到边界，继续放宽负载只会恶化分位。具体例子：若驱逐在批形成前完成且打分准确，会话增长带来的额外块主要是低分块，被逐出后重算量小，斜率平缓；若打分依赖图查询在会话后期变慢（因为触及文件子图变大），斜率会因CPU开销而非GPU重算而变陡——这两种陡峭的成因必须分开归因，否则会误判为显存不足。</p>\n<p>另一个反向限制是批大小的上界。驱逐策略若要求批级视图，批调度器就不能无限扩大批——批越大，批内块冲突率越高，驱逐决策的复杂度上升。工程判断是：批大小应有一个由块冲突率反馈的上界，而不是单纯由显存反推。这与连续批处理的常规做法不同，后者通常只按显存与算力定批大小；在上下文感知驱逐下，批大小还受索引一致性的约束。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-12\">十二 · 可核查的测量清单与Blackwell档位的对应</h3>\n<p>把上述口径落成一份可执行的清单，每一项都必须在Blackwell部署档位上可采集。第一，按请求类型分桶的输入长度分布与块数分布，报P50/P90/P99。第二，TTFT三段分解（匹配打分、驱逐规划、prefill）的分位。第三，命中率与重算token数按会话轮次区间的曲线，用于判断冷启动与稳态的分界。第四，批内块冲突率与批大小直方图的联合分布。第五，驱逐后首次未命中的TTFT增量分布，按驱逐原因分桶。第六，会话长度-延迟弹性斜率。</p>\n<p>与Blackwell特性的对应：KV若采用NVFP4/FP8量化，单块字节数 s 下降，可行域 n·k·s ≤ M 中的 k 上界提高，驱逐频率下降，但量化带来的数值误差会影响重算块与保留块拼接后的一致性——这一点材料未给出，需在实测中检查拼接后的补全质量是否退化。tcgen05与TMEM的使用影响prefill段的实际耗时，进而影响TTFT三段分解中第三段的基线。分离式预填/解码若启用，驱逐决策应放在预填侧，因为预填侧掌握前缀匹配结果；解码侧不应再触发驱逐，这与“驱逐前移到批调度之前”的原则一致。</p>\n<p>最后落在工程判断上：这套方案的可核验性瓶颈不在GPU侧，而在打分与依赖图的CPU开销是否被计入TTFT关键路径。若把打分做成异步预计算——请求进入前由会话管理器增量维护块分数，请求到达时只做查表——则打分开销从关键路径移出，净收益公式中的 t_score 项趋近于零，策略在低命中场景下也不再是负优化。这一改动不改变论文的打分语义，只改变其执行位置，是Blackwell部署档位上最值得先做的工程调整。</p>\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-13\">十三 · 从驱逐分数到 kernel 选择：为什么数值精度是驱逐策略的隐藏变量</h3>\n<p>上下文感知驱逐的目标是在固定 KV 预算下最大化保留块的复用价值，而“预算”本身不是抽象数字，它由数据类型直接换算成字节。同一个 <span class=\"formula-inline\">S(b)</span> 排序结果，在 BF16 KV 下能保留的块数只有 FP8 的一半、NVFP4 的四分之一左右（按每元素位宽比例）。因此驱逐策略的上限不是打分器决定的，而是 KV 元素的数值格式决定的：精度越低，单位显存能容纳的保留块越多，<span class=\"formula-inline\">S(b)</span> 中高依赖块的存活概率越高，重算 token 数下降。代价转移到 kernel 侧——低精度 KV 的读取、反量化与注意力累加必须由第五代 Tensor Core 的特定指令路径承接，否则省下的显存会被额外的转换开销吃掉。</p>\n<p>本部分只讨论这条链路：核心 attention kernel 在 Blackwell 上如何消费不同精度的 KV 块、累加精度如何影响驱逐后的重算正确性、以及 tcgen05/TMEM/2-SM MMA 这些特性如何改变“保留更多块”的实际延迟代价。驱逐打分公式本身的信号构成见本卷其他片段，此处不重复。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-14\">十四 · 核心 kernel 的数据通路：QK^T 与 PV 两段的精度分工</h3>\n<p>解码期 attention 由两段矩阵乘构成：<span class=\"formula-inline\">QK^T</span> 产生分数，经 softmax 后与 V 相乘得到输出。Blackwell 上的高效实现把这两段都交给 tcgen05 MMA，但两段的输入精度与累加策略不同。Q 通常保持较高精度（BF16 或 FP8），K 与 V 则是被驱逐策略管理的对象，可能以 FP8 或 NVFP4 存储。tcgen05 的 MMA 指令在硬件内完成低精度输入到 FP32 累加的转换，累加器驻留在 TMEM 而非寄存器堆，这使长序列的分数矩阵不必反复溢出到共享内存。</p>\n<div class=\"formula\">$$\\text{Attn}(Q,K,V)=\\text{softmax}\\!\\left(\\frac{QK^{\\top}}{\\sqrt{d}}\\right)V,\\qquad \\text{acc}_{QK}\\in\\text{FP32},\\ \\text{acc}_{PV}\\in\\text{FP32}$$</div>\n<p>逐项解释：<span class=\"formula-inline\">\\(QK^{\\top}\\)</span> 的乘加在 Tensor Core 内以 FP32 累加，避免低精度 K 的量化误差在长上下文上累积成分数排序错误；<span class=\"formula-inline\">\\(\\sqrt{d}\\)</span> 缩放必须在 softmax 之前以 FP32 完成，否则 FP8 分数在指数运算前就可能饱和；<span class=\"formula-inline\">PV</span> 段的累加同样要求 FP32，因为 V 的低精度误差会直接进入输出隐状态，经残差与 LayerNorm 放大。工程含义是：KV 可以低精度存储，但两段累加器不能降精度，TMEM 的容量因此成为并发上限的硬约束——每个活跃请求的累加器占用 TMEM 分区，TMEM 分区数固定，驱逐策略释放的是 HBM 中的 KV 块，释放不了 TMEM 中的累加器。</p>\n<p>具体例子：一个仓库级补全请求在解码时命中若干函数定义块，这些块的 K/V 以 FP8 存放；QK^T 段读取 FP8 K 并在 TMEM 中 FP32 累加，softmax 后 PV 段读取 FP8 V 同样 FP32 累加。若把 V 降到 NVFP4，PV 段的输出误差会随 V 的块缩放因子粒度变化，块内动态范围大的代码 token（如长数字字面量、密集运算符行）更容易失真。驱逐策略若把“低精度可存更多块”当作无条件收益，就会在重算回填时把量化误差引入本已命中的块，破坏前缀复用的一致性。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-15\">十五 · 累加精度与误差传播：驱逐后重算的数值一致性</h3>\n<p>驱逐策略的一个隐含要求是：命中块复用的 KV 与未命中块重算出的 KV 在数值上足够接近，否则同一前缀在不同请求间产生不一致的 attention 输出，表现为补全结果的抖动。这要求重算路径与缓存路径使用相同的量化格式与相同的累加顺序。若缓存中的 K 是 FP8、重算时却以 BF16 写入再量化，舍入方向可能不同，块缩放因子也可能落在不同区间。</p>\n<div class=\"formula\">$$\\varepsilon_{\\text{out}}\\ \\approx\\ \\sum_{i}\\left|\\Delta K_i\\right|\\cdot\\left|\\frac{\\partial\\,\\text{softmax}_i}{\\partial K_i}\\right|+\\sum_{j}\\left|\\Delta V_j\\right|\\cdot\\left|p_j\\right|$$</div>\n<p>逐项解释：第一项是 K 的量化扰动经 softmax 敏感度放大的贡献，softmax 对分数差异的敏感度在分数接近时最高，因此语义相近的候选 token（补全场景中大量存在的同义标识符）对 K 误差最敏感；第二项是 V 的扰动按注意力权重 <span class=\"formula-inline\">p_j</span> 加权，权重集中的位置误差影响大，权重分散的长尾位置误差被平均掉。工程判断：驱逐策略应优先保留那些 attention 权重集中、K 分数差异大的块（通常是当前编辑位置附近的强依赖符号），因为这些块的数值误差最不容易被平均；相反，历史会话中权重弥散的块即使被逐出，重算误差对输出的影响也较小。</p>\n<p>系统代价：FP32 累加使 TMEM 占用翻倍于 FP16 累加，直接压低可同时驻留的请求数；若为省 TMEM 改用 FP16 累加，长上下文下分数排序可能出现翻转，softmax 后的 top-k 选择变化，补全的候选 token 排序随之抖动。这是延迟之外的隐性代价——首 token 延迟分位可能不变，但补全接受率下降，等效吞吐下降。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-16\">十六 · Blackwell 特性如何改变驱逐的经济性：tcgen05、TMEM、2-SM MMA</h3>\n<p>tcgen05 的关键变化是 MMA 由单线程发射、异步执行，累加器在 TMEM 中由硬件管理，算子可以流水化地发起多个 MMA 而不阻塞。对驱逐策略而言，这意味着“重算未命中块”的预填成本可以被更细粒度地重叠进解码流水：驱逐发生在批调度之前，重算的 prefill 段与上一批的解码段可以在不同 SM 上并行，只要 TMEM 分区够用。TMEM 容量因此成为驱逐与重算耦合的调度资源，而不只是 attention 的内部缓冲。</p>\n<p>2-SM MMA（成对 SM 协作执行一次 MMA）把单个 MMA 的吞吐提高，但要求两个 SM 的 TMEM 协同分配。驱逐策略若在批内混合了不同长度的请求，2-SM 配对会受批形状约束：长短请求混批时配对效率下降，低精度 KV 省出的显存未必转化为吞吐。工程上应把驱逐后重算的块按长度聚类，使 2-SM 配对发生在形状相近的请求之间。</p>\n<table class=\"mini\"><thead><tr><th>KV 格式</th><th>单位块显存</th><th>累加要求</th><th>驱逐收益</th><th>主要代价</th></tr></thead><tbody><tr><td>BF16</td><td>基准</td><td>FP32</td><td>保留块数最少</td><td>显存压力最大</td></tr><tr><td>FP8</td><td>约一半</td><td>FP32</td><td>保留块数翻倍</td><td>需块缩放因子管理</td></tr><tr><td>NVFP4</td><td>约四分之一</td><td>FP32</td><td>保留块数最多</td><td>块内动态范围失真、重算一致性难保证</td></tr></tbody></table>\n<p>具体例子：GB200 NVL72 单机架内多 GPU 共享大容量 HBM，KV 预算相对宽松，驱逐压力小，BF16 或 FP8 即可支撑长会话；单卡 B200 部署时预算紧张，NVFP4 KV 把可保留块数放大，但必须接受 PV 段误差与重算一致性校验的开销。同一驱逐算法在两种档位下的最优精度不同，打分权重也应随精度档位调整——低精度档位下应提高依赖项权重，因为逐出后重算的误差代价更高。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-17\">十七 · 逐出决策与 kernel 执行的时序耦合</h3>\n<p>驱逐前移到批调度之前，意味着 kernel 看到的 KV 布局在批形成时就已固定。tcgen05 的异步 MMA 要求 K/V 的页表与块索引在发射前确定，解码中途改变布局会强制流水线排空。因此驱逐不仅要在调度前完成，还要在 KV 页分配器层面落实：被逐出的块释放物理页，重算块在 prefill kernel 中写入新页，索引回填后下一批才能引用。</p>\n<div class=\"formula\">$$T_{\\text{batch}}\\ \\approx\\ T_{\\text{evict}}+T_{\\text{recompute}}+T_{\\text{decode}},\\qquad T_{\\text{recompute}}\\propto N_{\\text{miss}}\\cdot L_{\\text{block}}$$</div>\n<p>逐项解释：<span class=\"formula-inline\">\\(T_{\\text{evict}}\\)</span> 是打分与页释放的 CPU 侧开销，随依赖图规模增长；<span class=\"formula-inline\">\\(T_{\\text{recompute}}\\)</span> 与未命中块数 <span class=\"formula-inline\">\\(N_{\\text{miss}}\\)</span> 和块长度 <span class=\"formula-inline\">\\(L_{\\text{block}}\\)</span> 成正比，由 prefill kernel 承担；<span class=\"formula-inline\">\\(T_{\\text{decode}}\\)</span> 是命中块上的解码时间。驱逐策略的收益条件是 <span class=\"formula-inline\">\\(T_{\\text{recompute}}\\)</span> 的下降超过 <span class=\"formula-inline\">\\(T_{\\text{evict}}\\)</span> 的上升。低精度 KV 使 <span class=\"formula-inline\">\\(N_{\\text{miss}}\\)</span> 下降（保留块更多），但 FP8/NVFP4 的 prefill kernel 需要额外的量化与缩放因子计算，<span class=\"formula-inline\">\\(T_{\\text{recompute}}\\)</span> 的单位成本上升，收益条件变严。</p>\n<p>工程判断：在 Blackwell 上应把驱逐打分与页分配放在同一调度周期内，用 TMEM 分区余量作为是否触发驱逐的判据之一——TMEM 紧张时即使 HBM 有余也应及时逐出低分块，避免解码段因累加器不足而降级为分片执行。这一判据把显存预算与计算资源预算统一到驱逐决策里，是纯时间序 LRU 无法表达的。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-18\">十八 · 精度档位下的驱逐参数与可观测项</h3>\n<p>驱逐打分公式中的 <span class=\"formula-inline\">\\(\\delta\\cdot C(b)\\)</span> 项代表逐出与重算代价，其量纲应随 KV 精度变化：BF16 下重算成本主要是 HBM 带宽与 prefill 算力，NVFP4 下还要加上量化误差导致的重算一致性校验成本。部署期在线调参若只依据命中率与首 token 延迟分位，会忽略补全接受率这一与精度强相关的指标。可观测项应包含：命中块的精度格式分布、重算块的量化误差统计（与缓存路径的 KL 散度或输出差异）、TMEM 分区占用率、2-SM 配对成功率。</p>\n<p>具体机制：在监控侧为每个被逐出后又重算的块记录其输出隐状态与“若未逐出”路径的差异，作为 <span class=\"formula-inline\">C(b)</span> 的实测代理；当差异超过阈值时提高该块所属符号类别的保留权重，等价于在打分器里引入精度敏感项。这不需要梯度训练，属于部署期反馈闭环，与论文的在线调参路径一致。代价是校验本身消耗算力，应只在低精度档位开启，BF16 档位下可关闭以省开销。</p>\n<p>最终落点是一个工程判断：上下文感知驱逐的收益上界由 KV 精度决定，而精度选择又受累加器容量与 kernel 路径约束；在 Blackwell 上把 tcgen05 的 TMEM 余量、2-SM 配对形状与 KV 格式纳入同一调度决策，才能让“保留更多高依赖块”真正转化为首 token 延迟分位的下降，而不是把显存节省换成重算误差与流水线排空。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-19\">十九 · 语义打分的开销边界与失效条件</h3>\n<p>上下文感知驱逐的收益并非无条件成立，其边界首先由打分链路自身的资源占用决定。依赖图构建与块打分发生在请求进入、批形成之前，属CPU侧与索引侧开销：每来一个仓库级请求，都要按文件与符号边界切块、做前缀匹配、再对候选块计算引用关系与阶段信号。这部分开销与<em>候选块数量</em>成正比，而候选块数量随仓库规模与上下文长度增长。当命中率收益不足以覆盖这部分固定开销时，策略反而拖慢首token延迟。工程上的判据是：把打分耗时与重算节省的token时间放在同一量纲上比较，若前者在批调度窗口内无法被隐藏，就应退化为纯时间序驱逐或缩小依赖图解析深度。KV量化（NVFP4/FP8）能扩大可保留块数，但也会放大索引与打分的相对占比——块越多，依赖图越宽，打分越贵。</p>\n<p>失效条件集中在三类场景。其一，缓存冷启动：前缀缓存尚未积累，命中率低，此时驱逐策略几乎没有可保留的高分块，收益趋近于零，需与分离式预填协同评估，否则打分开销纯属净损失。其二，解码中途逐出：若因调度耦合失误在解码过程中触发逐出，会打断批内其他请求并引发重算抖动，因此逐出必须严格前移到批形成之前，这是硬约束而非优化项。其三，超大仓库的跨文件依赖解析：引用图可能跨越大量文件与符号，解析深度与索引规模的可扩展性材料未给出，工程上应以解析深度上限和块粒度作为两个可调闸门，避免依赖图构建成为长尾延迟来源。</p>\n<div class=\"formula\">$$T_{\\text{score}} = N_b \\cdot (c_{\\text{match}} + c_{\\text{dep}}) + T_{\\text{evict}},\\quad \\text{收益条件：} \\; \\Delta T_{\\text{recompute}} &gt; T_{\\text{score}}$$</div>\n<p>式中 $N_b$ 为候选块数，$c_{\\text{match}}$ 为单块前缀匹配代价，$c_{\\text{dep}}$ 为单块依赖解析代价，$T_{\\text{evict}}$ 为逐出与重算规划耗时；$\\Delta T_{\\text{recompute}}$ 为被保留块所避免的重算token时间。该式给出一个明确的工程判断：只有当重算节省超过打分链路开销时，语义驱逐才划算。以一次仓库级补全为例，若当前编辑位置只引用少数跨文件符号，高分块集中在少量函数与类型定义上，$N_b$ 虽大但有效依赖稀疏，此时应压缩依赖解析范围而非全图遍历；反之在agent多轮循环中复用频次信号权重上升，命中块稳定，打分开销可被摊薄。系统代价最终落在CPU占用与首token延迟分位上，而非显存——显存收益来自保留块数增加，代价则来自索引与打分的算力与延迟，二者必须在同一SLO口径下实测平衡点。</p>\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-20\">二十 · 显存账本的三层结构与可复算预算</h3>\n<p>在Blackwell上给一个仓库级代码补全服务做容量规划，第一件事不是选框架，而是把显存拆成三本账：权重、激活、KV。三者的增长规律完全不同——权重是常数，激活随批内token数与序列长度线性走，KV则随“并发×上下文长度×层数×KV头数×头维×精度字节”走，并且是本部分的主角。以B200的HBM3e容量为200GB量级、GB200 NVL72单GPU同档来算，一张卡上先扣掉权重与框架预留，剩下的才是KV预算。设权重参数量为P、权重精度字节为b_w，则权重占用</p>\n<div class=\"formula\">$$M_{w}=P\\cdot b_{w}$$</div>\n<p>一个70B级模型在FP8下约70GB，NVFP4下约35GB；再加上CUDA context、通信缓冲、临时workspace，工程上按权重占用的1.1–1.2倍预留比较稳。激活部分取决于批内总token数B·L与隐藏维、中间维，prefill阶段远大于decode阶段，分离式部署时预填实例与解码实例的激活账要分开算。剩下的KV预算才是驱逐策略真正博弈的空间。</p>\n<p>KV单token占用可写成</p>\n<div class=\"formula\">$$M_{kv}^{tok}=2\\cdot n_{layer}\\cdot n_{kv}\\cdot d_{head}\\cdot b_{kv}$$</div>\n<p>系数2是K与V。以GQA模型n_layer=80、n_kv=8、d_head=128、FP8（b_kv=1）为例，单token约164KB；若换NVFP4（约0.5字节有效），降到约82KB。这个数字直接决定“能保留多少块”：一个仓库级请求带32K上下文，FP8下约5.2GB，NVFP4下约2.6GB。若单卡KV预算按120GB计，前者可支撑约23路并发，后者约46路——这就是量化KV对并发数的直接杠杆，也是论文主张与NVFP4/FP8结合时收益的来源。注意这里没有实验数字，全部由公式复算得出，读者应代入自己模型的层数与头数重算一遍。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-21\">二十一 · 分页与块索引：驱逐的物理单位</h3>\n<p>论文的驱逐对象是“上下文块”，但落到显存上必须是分页的物理块。PagedAttention式管理把KV切成固定token数的page（常见16或32 token），块表记录逻辑块到物理page的映射。论文的分块KV索引与依赖图必须挂在这层page表之上：一个代码块（函数、类型定义、跨文件符号）可能横跨多个page，驱逐一个语义块意味着回收其全部page。这里有一个容易被忽略的代价：语义块与物理page不是一一对应，块边界按文件与符号切，page边界按token数切，二者错位会造成“半块驻留”——一个函数体被逐出但它的签名page仍被别的块引用，回收不干净，实际可用预算被侵蚀。</p>\n<p>工程上的做法是给每个page维护引用计数，语义块的驱逐先解引用再回收，回收后的page进空闲池供重算回填。伪代码思路：</p>\n<ul>\n<li>请求进入 → 前缀匹配得到候选块集合 → 对每块查page表，命中则引用计数+1；</li>\n<li>打分排序 → 低分块解引用，引用计数归零的page入空闲池；</li>\n<li>批调度前完成上述回收，解码期间page表只读，不触发回收；</li>\n<li>未命中块重算后申请空闲page，回填块表与依赖图。</li>\n</ul>\n<p>这套流程的显存代价是块表与依赖图本身：每page一条映射、每块一组依赖边，超大仓库下依赖图可能达到数万节点，常驻内存虽不在HBM但在host侧，跨文件解析的CPU开销会与GPU空转耦合。论文未给出索引构建开销，这正是部署时必须实测的部分——如果打分与索引的CPU时间超过批调度窗口，驱逐前移的收益会被抵消。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-22\">二十二 · 压缩、复用与卸载：三条扩容路径的代价</h3>\n<p>在预算固定时，扩大可保留块数只有三条路。第一条是压缩：KV量化到FP8或NVFP4，按上面的公式直接减半或更多；代价是数值精度对长上下文注意力分布的影响，代码场景对精确token匹配敏感（标识符、数字字面量），量化误差可能表现为补全里符号拼写漂移，需要在评测里盯住。第二条是复用：前缀缓存命中即复用，这是论文的主路径，收益等于“省下的重算token数×每token重算的算力与带宽”。重算一个32K上下文在prefill阶段的代价是O(L²)注意力加O(L·d²)投影，省一次就是省一次完整预填，对首token延迟的贡献最直接。第三条是卸载：把低分块的KV换出到host内存或NVMe，需要时再换回。卸载的瓶颈不在容量而在链路——PCIe Gen5 x16双向约128GB/s量级，而HBM3e单GPU带宽是TB/s级（B200在8TB/s量级），换出再换回一个5GB的块在PCIe上就是几十毫秒级，足以打穿首token延迟SLO。因此卸载只适合“确定长时间不会再被引用”的块，且要与分离式预填/解码的拓扑配合：预填实例算完即卸，解码实例按需拉取。</p>\n<p>三条路径的工程判断是：压缩优先（无链路代价），复用其次（依赖命中率），卸载最后（链路代价高）。论文的打分函数里R(b)复用概率与D(b)依赖强度正是决定“哪些块值得留在HBM”的信号，而C(b)成本项应当把重算代价与换入换出代价都算进去，否则会把高重算成本的块误判为可逐出。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-23\">二十三 · 带宽瓶颈的定位：decode是带宽活，驱逐是延迟活</h3>\n<p>Blackwell上推理的带宽瓶颈要分阶段看。decode阶段每生成一个token，要把全部权重读一遍（或按MoE激活部分读），算术强度极低，是纯带宽受限：单token时间下界约等于权重字节数除以HBM带宽。70B FP8权重70GB、8TB/s带宽，理论下界约9ms/token，这是任何调度技巧都突破不了的墙。prefill阶段则是算力受限，tcgen05与2-SM MMA把MMA吞吐拉高，长上下文的注意力成为主项。KV驱逐影响的是prefill的重算量与decode的KV读取量：decode每步要读全部驻留KV，驻留越长，每token的KV读取字节越多，带宽压力越大。所以“保留更多块”并非免费——它抬高decode的每步带宽占用，在长上下文高并发下会把decode从带宽受限推向更紧的带宽受限。</p>\n<p>这就是为什么驱逐策略必须与批调度耦合：批内每个请求的驻留KV长度决定了这一步的总读取量，批形成前按预算逐出低分块，等价于给这一步的带宽需求封顶。若在解码中途逐出，批内其他请求的步进被打断，重算插入造成延迟抖动——论文把逐出前移的动机正在此。定量地看，一步decode的KV读取字节约为</p>\n<div class=\"formula\">$$B_{step}=\\sum_{i\\in batch} L_i \\cdot M_{kv}^{tok}$$</div>\n<p>若批内平均驻留32K、批大小16、FP8单token 164KB，则一步读取约86GB，按8TB/s需约11ms，已经超过权重读取的下界，成为decode主瓶颈。把驻留压到16K就减半。这个算式说明：KV预算不只是容量问题，它直接写进了decode的带宽账本，驱逐的“保留窗口”本质上是在容量与带宽之间划一条线。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-24\">二十四 · 一个可复算的部署预算例</h3>\n<p>给一个具体例子，读者可代入自己的参数复算。设模型70B、GQA n_layer=80、n_kv=8、d_head=128；单卡HBM 200GB；权重NVFP4约35GB，框架与通信预留按1.2倍计42GB；激活按prefill批8K token、decode批16路各留8GB，共16GB；则KV预算约200−42−16=142GB。KV用FP8，单token 164KB，则总可驻留token数约142GB/164KB≈86万token。若目标并发64路、每路平均上下文24K，需64×24K=154万token，超预算约1.8倍——此时驱逐策略必须把每路驻留压到约13.4K，或者把KV换成NVFP4把预算翻倍到172万token刚好覆盖。这就是论文打分器要解的约束：在86万token的池子里，按S(b)排序保留高复用块，把低分块逐出并规划重算。</p>\n<p>代价侧要同步算：每逐出一个24K上下文的块，重算约24K token的prefill，按算力受限阶段的时间量级是数十毫秒，若命中率不足，首token延迟分位会被重算主导。因此监控必须同时看命中率、重算token数与首token延迟分位三个量，缺一个就无法判断驱逐是赚是亏。论文未给出这些数值，部署方需在自己的仓库请求流上实测。表格给出三档量化下的预算对比，便于横向判断：</p>\n<table class=\"mini\"><thead><tr><th>KV精度</th><th>单token占用</th><th>142GB可驻留token</th><th>64路×24K是否够</th><th>主要代价</th></tr></thead><tbody><tr><td>FP8</td><td>约164KB</td><td>约86万</td><td>不够，需压驻留或降并发</td><td>精度误差小，容量紧</td></tr><tr><td>NVFP4</td><td>约82KB</td><td>约172万</td><td>刚好覆盖</td><td>精度误差需评测，容量松</td></tr><tr><td>FP8+卸载</td><td>驻留164KB，换出走PCIe</td><td>视换出比例</td><td>可覆盖但换入延迟高</td><td>链路毫秒级，打穿SLO风险</td></tr></tbody></table>\n<p>这张表的意义不是给出结论，而是把“容量—并发—精度—链路”四个变量放进同一个算式里，让驱逐策略的保留窗口成为可调参数而非拍脑袋的固定值。论文的在线调参闭环（按命中率与延迟分位更新权重）在这个框架下才有落点：调的是保留窗口与打分权重，约束是上面这条预算等式。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-25\">二十五 · 冷启动与索引开销：预算账本外的隐项</h3>\n<p>预算等式里还有两项常被漏算。其一是缓存冷启动：新会话或新仓库首次请求时前缀缓存为空，命中率接近零，驱逐策略无从发挥，此时全部上下文都要预填，KV瞬时占用达到峰值。若并发在冷启动时刻集中涌入，峰值KV可能超过预算，触发强制逐出，而逐出的又都是刚算出来的块——这是最坏情况，重算率最高。工程上要给冷启动留出预留池，或按会话阶段（论文的F(b)阶段信号）在冷启动期放宽保留窗口、在稳定期收紧。其二是索引与依赖图的构建开销：分块、跨文件引用解析、打分排序都在CPU侧，若单请求耗时超过批调度周期，GPU会出现空泡，等效吞吐下降。论文未给出该开销，部署时应把它计入SLO预算，而不是当作免费收益。</p>\n<p>把这两项放回账本，可复算的预算应写成：可用KV预算 = HBM容量 − 权重×1.2 − 激活峰值 − 冷启动预留 − 索引常驻（host侧不计入HBM但影响调度）。驱逐策略的保留窗口在这个余量内取值，并按会话阶段动态调整。最终落在具体机制上：驱逐不是容量不足时的补救，而是把“哪些代码块值得占用HBM带宽与容量”这一判断前移到批形成之前，用引用关系与复用概率替代访问时间序；它的收益上限由命中率决定，下限由索引与重算开销决定，二者在Blackwell档位上必须同时实测才能定参。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-26\">二十六 · 驱逐策略的边界：打分开销、冷启动与跨文件解析的代价</h3>\n<p>上下文感知驱逐并非免费收益，它的第一个失效条件来自打分链路自身。每个请求进入时都要做前缀匹配、块打分与依赖图查询，这些工作在 CPU 侧完成，与 GPU 上的预填/解码争抢调度窗口。设单请求块数为 <span class=\"formula\">$$N_b$$</span>、每块打分与依赖查询代价为 <span class=\"formula\">$$c_s$$</span>，则单请求额外 CPU 时延约为 <span class=\"formula\">$$T_{score}=N_b\\cdot c_s$$</span>。当仓库级上下文把 <span class=\"formula\">$$N_b$$</span> 推到数百量级，而 SLO 要求首 token 延迟落在个位数毫秒分位时，这段串行开销会直接吃掉驱逐带来的重算节省。工程判断是：打分必须在批形成前的空闲窗口内完成，且依赖图查询要能走内存索引而非每次重新解析符号；否则应退化为只对候选逐出块打分，命中块走快速路径。</p>\n<p>第二个边界是缓存冷启动。驱逐策略的收益来自“保留高复用块”，而冷启动阶段前缀缓存命中率接近零，此时任何打分都缺乏近期复用频次信号，<span class=\"formula\">$$R(b)$$</span> 项失真，策略退化为近似随机保留。更严重的是，冷启动期若仍按预算逐出，会把尚未被引用但即将被引用的类型定义与跨文件符号提前清出，导致首 token 延迟分位出现尖峰。可复算的账本是：给定 KV 预算 <span class=\"formula\">$$M_{kv}$$</span>、每 token 每层 KV 字节数 <span class=\"formula\">$$s_{kv}$$</span>、层数 <span class=\"formula\">$$L$$</span>，可保留 token 数为 <span class=\"formula\">$$N_{tok}=M_{kv}/(s_{kv}\\cdot L)$$</span>；若采用 FP8/NVFP4 量化 KV，<span class=\"formula\">$$s_{kv}$$</span> 下降，<span class=\"formula\">$$N_{tok}$$</span> 上升，但量化误差会改变重算块的数值一致性，需在回填索引时保证同一块的重算与复用走同一精度路径。</p>\n<p>第三个失效条件是超大仓库下的依赖图可扩展性。跨文件引用解析需要构建符号级图，节点数与边数随仓库规模增长，材料未给出该图在超大仓库下的构建与查询复杂度。若图构建放在请求路径上，单次解析可能引入数十毫秒级抖动；若放在离线侧，则图的新鲜度与编辑位置脱节，打分依据过时。表格给出三种部署取舍的代价对比：</p>\n<table class=\"mini\"><thead><tr><th>取舍</th><th>命中收益</th><th>系统代价</th><th>适用条件</th></tr></thead><tbody><tr><td>全量块打分 + 在线依赖图</td><td>最高，语义信号完整</td><td>CPU 串行时延高，图构建抖动</td><td>中小仓库、低并发</td></tr><tr><td>仅候选逐出块打分</td><td>中等，命中块快速路径</td><td>打分开销可控，漏判风险上升</td><td>长会话高并发</td></tr><tr><td>离线图 + 定期刷新</td><td>较低，新鲜度滞后</td><td>请求路径无解析开销</td><td>超大仓库、编辑稀疏</td></tr></tbody></table>\n<p>最后，驱逐与重算规划依赖前缀缓存命中质量：命中率低时，逐出低分块只是把重算推迟到解码阶段，重算 token 数不降反升，因为被逐出的块可能在下一请求中立刻被引用。监控侧应把逐出次数、重算 token 数与首 token 延迟分位联合观察，当重算 token 数随逐出次数同步上升时，说明打分权重与保留窗口已偏离实际复用分布，需回调 <span class=\"formula\">$$\\alpha,\\beta,\\gamma,\\delta$$</span>；材料未给出调参周期与稳定性证据，这一闭环在部署期必须靠线上分位反馈而非离线假设来收敛。</p>\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-27\">二十七 · 驱逐决策嵌入连续批处理循环的位置</h3>\n<p>上下文感知驱逐要真正降低首token延迟抖动，关键不在于打分公式本身，而在于它被放在批处理循环的哪个位置。连续批处理（continuous batching）在每一步解码后把已完成的序列移出批、把新到达的请求插入批，批的成员在token级粒度上变化。若驱逐发生在解码中途，被逐出块的所属请求必须暂停、重算、再回填索引，而同一批内其他请求仍在推进，调度器要么空转等待，要么把该请求踢出批重排——两种处理都直接抬高端到端延迟的尾部。论文把逐出前移到批形成之前，等价于把驱逐变成一次“准入控制”：请求进入调度队列时先做前缀匹配与块打分，在KV预算约束下确定哪些块保留、哪些块重算，然后才组装本轮的批。这样解码过程中KV块集合对批内所有序列是稳定的，不会出现中途失效。</p>\n<p>工程上这要求调度器维护两个解耦的队列：等待队列（已完成分块、打分与预算裁决）与运行队列（已锁定KV块、正在解码）。裁决阶段的伪代码思路是：对等待队列中每个请求计算其候选块集合的保留代价，按全局KV预算做一次贪心或按分数阈值的裁剪，把低分块标记为待重算，再把剩余预算分配给可立即运行的请求。代价体现在调度延迟上：裁决本身消耗CPU时间与索引查询，且贪心裁剪在请求数多时是O(n log n)量级；收益体现在解码阶段零驱逐、零中途重算。对SLO敏感的服务，这个交换通常是划算的，因为首token延迟的分位数主要由排队与预填决定，而解码抖动会被放大到每一个输出token上。</p>\n<p>具体例子：一个agent循环在同一会话里连续发起“读文件—改函数—跑测试”三次补全，第二次请求携带的上下文包含第一次命中的函数定义块。若驱逐发生在第二次解码中途，该函数块被逐出，第三次请求又要重算它；而把驱逐前移到第二次请求准入时，打分器看到该块被后续编辑位置引用（D(b)项高），直接保留，第三次请求前缀命中，首token延迟不再包含这段重算。这里没有给出任何具体毫秒数，但机制上的差别是可判定的：抖动来源从“每个解码步都可能触发”收敛为“仅在请求边界触发”。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-28\">二十八 · Chunked prefill 与驱逐预算的耦合</h3>\n<p>Chunked prefill把长上下文的预填切成若干块，分多个调度步送入，目的是不让一个超长请求独占整个批、把其他请求的解码步饿死。它与驱逐策略的耦合点在于：预填块是KV写入的主要来源，而驱逐是KV释放的主要手段，两者共享同一份预算。若预填按固定chunk大小推进而不看驱逐裁决，可能出现“刚写入的块在下一轮就被判为低分逐出”的往返浪费；反之若驱逐过于保守，预填chunk会被预算卡住，长请求的首token延迟被拉长。</p>\n<p>可操作的耦合方式是让预填chunk的划分参考块打分：高分块（被当前编辑位置引用、跨文件符号定义）优先进入预填，低分块延迟预填或直接走重算路径而不占常驻预算。用公式表达预算约束下的预填调度优先级，可写成对每个待预填块按分数与剩余预算的比值排序：</p>\n<div class=\"formula\">$$\\text{priority}(b)=\\frac{S(b)}{\\text{cost}_{\\text{prefill}}(b)+\\lambda\\cdot\\text{bytes}(b)}$$</div>\n<p>其中分母同时计入预填算力代价与常驻显存代价，λ是部署期可调的换算系数。这个排序在每个调度步重算一次，使预填顺序随会话阶段漂移——编辑位置移动后，原先低分的块可能升分，从而被提前预填。代价是每步一次排序的CPU开销与分数缓存的失效维护；收益是预填算力花在真正会被复用的块上，减少“预填了又被逐出”的无效写入。带宽侧的代价同样存在：预填块写入KV要占HBM写带宽，若与解码读带宽竞争，chunk划分过细会放大这种竞争。</p>\n<p>具体例子：仓库级补全请求携带跨三个文件的上下文，其中两个文件的类型定义块被当前编辑位置直接引用，第三个文件的历史会话块仅被上一轮用到。按上式排序，前两个块进入首批chunk预填并锁定保留，第三个块延后预填；若预算在首批后被占满，第三个块直接标记为重算候选而非先写后逐。这避免了“写入—逐出—再写入”的两轮HBM写带宽消耗，而写带宽在长上下文预填阶段本就是稀缺资源。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-29\">二十九 · 优先级、抢占与尾延迟的压制路径</h3>\n<p>交互式编程的请求并非同质：用户敲下补全触发的请求对首token延迟极敏感，agent循环里的批量重构请求则可以容忍更长排队。优先级调度因此不是可选项而是必需项，但优先级一旦引入就必须回答抢占问题——高优先级请求到达时，是否把正在解码的低优先级序列踢出批？踢出的代价是该序列的KV块要么保留占预算、要么被逐出后重算，两者都消耗资源。论文的驱逐前移机制在这里给出一个较干净的答案：抢占发生在请求边界而非解码中途，被抢占序列的KV块在下一轮准入时重新打分，高分块保留、低分块逐出，重算成本被显式计入下一轮的预填预算，而不是在解码中途突然插入。</p>\n<p>尾延迟的压制路径可以拆成三段：排队尾、预填尾、解码尾。排队尾由优先级与准入裁决控制，高分请求插队但受KV预算约束；预填尾由chunk划分与预填优先级控制，长上下文不再独占批；解码尾由驱逐前移消除中途重算抖动。三段中任何一段失控都会在P99上体现，而三段共享同一份KV预算，所以容量规划必须按“最坏情况下的保留块数”而非平均命中率来定预算。用定性表述：若按平均命中率配置预算，高峰期的准入裁决会频繁把中分块判为逐出，重算token数上升，首token延迟分位随之抬升；按分位场景配置则显存利用率下降。这个取舍没有免费解，只能靠监控侧的命中率与重算token数反馈来调打分权重与保留窗口。</p>\n<p>具体例子：同一服务同时承载IDE补全（高优先级、短上下文）与agent批量重构（低优先级、长上下文）。若不做抢占，长上下文请求的chunked prefill会占满批，IDE补全的首token延迟被排队拉长；若做解码中途抢占，被踢出的重构序列KV块失效，重算成本转嫁到下一轮。把抢占限定在请求边界、并让准入裁决按分数保留重构序列的高分块，则IDE补全获得插队权，重构序列只损失低分块的重算，尾延迟的来源被收敛到可预期的请求边界。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-30\">三十 · 分离式预填/解码下的驱逐归属</h3>\n<p>分离式预填/解码（disaggregated prefill/decode）把预填与解码放到不同实例甚至不同节点，KV块需要跨节点传输。这给驱逐策略带来一个新问题：驱逐决策归属哪一侧？预填侧产生KV块、解码侧消费KV块，若两侧各自按本地预算驱逐，会出现预填侧刚写入的块被解码侧判为低分逐出、或解码侧需要的块在预填侧已被释放的错配。论文的分块KV索引与依赖图若部署在服务侧统一维护，则驱逐裁决应放在请求路由层：请求进入时由路由层做前缀匹配与打分，决定该请求的KV块集合在预填侧与解码侧各保留多少，再把裁决结果随请求下发。</p>\n<p>代价结构在这里发生变化：跨节点传输KV块占用NVLink带宽与传输延迟，驱逐导致的重算若发生在预填侧，则重算的算力成本与传输成本叠加；若发生在解码侧，则解码步被拉长。因此分离式部署下，驱逐的判据要额外计入“传输代价”项，即公式中的C(b)不再只是重算算力，还包括该块若被逐出后重新获取所需的跨节点搬运成本。定性地说，跨节点搬运成本高的块应获得更高的保留优先级，这与单节点部署下“重算便宜的块可以先逐”的直觉相反。</p>\n<p>具体例子：GB200 NVL72机架内预填与解码分处不同GPU，一个跨文件符号定义块被多个解码实例共享引用。若各解码实例按本地预算独立驱逐，该块在每个实例上都被判为“本实例近期未用”而逐出，下次请求到来时每个实例各自向预填侧重新请求搬运，NVLink带宽被重复消耗。统一裁决则让该块在共享引用计数下降前保持保留，搬运只发生一次。这里材料未给出带宽数值，但机制上的重复搬运是可避免的。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-31\">三十一 · 时延与吞吐的取舍判据</h3>\n<p>连续批处理提高吞吐的机制是让批内序列在token级错峰推进，批越大、解码步的算力利用率越高，但单请求的首token延迟与解码间隔随之变长。驱逐策略在这个取舍里扮演的是“预算放大器”：保留更多块意味着更大批可以同时驻留，吞吐上升；但保留块占显存，可分配给新请求预填的预算下降，首token延迟上升。判据不能只看平均吞吐，要看在给定SLO下的最大可持续批大小。</p>\n<p>可操作的判据是把驱逐后的有效KV预算写成批大小的函数，再求满足首token延迟分位约束的最大批：</p>\n<div class=\"formula\">$$\\text{batch}_{\\max}=\\max\\{n:\\ \\text{P99}(\\text{TTFT}\\mid n,\\ \\text{kept blocks})\\le \\text{SLO}\\}$$</div>\n<p>其中kept blocks由打分与预算裁决决定，P99是经验分位而非解析式。工程上这意味着容量规划要做两件事：一是按分位场景而非均值场景估算保留块数，二是把打分权重的在线调整与批大小上限联动——命中率上升时放宽批大小，重算token数上升时收紧。代价是监控与调参的运维开销，收益是避免“平均吞吐好看但P99超标”的配置漂移。功耗侧同样有取舍：更大批意味着更高SM占用与更高功耗，在功耗封顶的机架里批大小上限可能先于显存上限成为约束。</p>\n<p>具体例子：一个仓库级补全服务在高峰期把批大小推到显存允许的上限，命中率因驱逐频繁而下降，重算token数上升，首token延迟P99抬升；把批大小按分位场景回调、同时提高高分块的保留权重后，单批吞吐下降但重算减少，P99回到SLO内。材料未给出具体阈值，但这条路径的因果链是可判定的：驱逐频率与批大小通过KV预算耦合，调批大小等价于调驱逐压力。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-32\">三十二 · 监控闭环与打分权重的在线调整</h3>\n<p>论文把打分权重放在部署期在线调参而非梯度训练，这意味着调度系统必须自带一个反馈回路：监控侧记录命中率、重算token数与首token延迟分位，反馈给权重更新。回路的设计要点是避免震荡——权重调整若跟随短窗口的命中率波动，会导致保留窗口频繁伸缩，驱逐裁决在相邻请求间不一致，反而增加重算。可操作的稳定化手段是对权重更新做低通滤波，并给保留窗口设最小驻留时间，使一个块在被判为低分后至少经历一个完整的批周期才真正逐出。</p>\n<p>监控项与调度动作的对应关系需要显式定义：命中率下降且重算token数上升，指向保留权重不足或预算过紧；首token延迟分位上升而命中率稳定，指向预填chunk划分或批大小问题而非驱逐问题；逐出次数上升但重算token数不升，说明被逐出的块确实不再被引用，驱逐策略有效。把这三类信号分开归因，才能避免把所有延迟问题都归到打分权重上。代价是监控埋点与归因逻辑的工程投入，收益是调参有据可依而非凭经验试。</p>\n<p>具体例子：agent循环在会话早期大量引用跨文件符号，会话后期编辑收敛到单文件，引用关系信号D(b)的权重在后期应下调、复用频次信号R(b)的权重应上调。若权重固定不变，后期仍按跨文件依赖保留大量块，挤占单文件补全的预填预算，首token延迟上升。在线调整若按会话阶段分段更新权重而非逐请求更新，可避免同一会话内裁决不一致。材料未给出调参周期与稳定性证据，这一环的工程风险在于权重漂移与监控噪声的耦合，需要在部署时用最小驻留时间与低通滤波兜底。</p>\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-33\">三十三 · 驱逐决策落在哪个并行维度上</h3>\n<p>上下文感知驱逐在单卡视角下是“KV 预算内的排序问题”，一旦落到 NVL72 机柜就变成“排序结果必须与并行切分对齐”的问题。分块 KV 索引按文件与符号边界切块，而张量并行（TP）把同一层的 KV 头切到不同 rank、专家并行（EP）把 MoE 专家分散到不同 GPU、流水并行（PP）把层段分到不同 stage、数据并行（DP）复制整份权重。驱逐一个块，意味着它在所有持有该块 KV 的 rank 上同时消失；若某个 rank 因本地预算先逐出、另一个 rank 仍保留，前缀匹配就会在集合通信前失配，触发跨 rank 的重算分歧。工程上的做法是把驱逐决策收敛到批调度器一侧：由调度器持有全局分块索引与依赖图，按公式</p>\n<div class=\"formula\">$$S(b)=\\alpha\\cdot R(b)+\\beta\\cdot D(b)+\\gamma\\cdot F(b)-\\delta\\cdot C(b)$$</div>\n<p>统一打分，再把“保留集合”作为批的附带元数据下发到各 rank，各 rank 只执行不决策。代价是调度器成为串行点：每次批形成前要遍历候选块并做依赖图查询，块数随仓库规模线性增长，这一段 CPU 时间直接叠加在首 token 延迟上。具体例子：一个 agent 循环在同一会话内连续发起多次补全，第二次请求的前缀命中依赖第一次请求保留的跨文件符号块；若 TP=8 的某个 rank 因本地碎片先逐出该块，其余 7 个 rank 的前缀缓存命中而它未命中，解码前的 All-Reduce 就要等它重算，抖动被放大到整批。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-34\">三十四 · NVLink 5 与 NVSwitch：什么时候通信不痛</h3>\n<p>Blackwell 机柜内 NVLink 5 与 NVSwitch 把单跳带宽抬到远高于 PCIe 代际的水平，NVLink 域内的 All-Reduce 与 All-to-All 在中小消息上主要受延迟而非带宽约束。对驱逐策略的直接含义是：TP 组内的 KV 重算同步、EP 组内的 token 路由，只要落在 NVLink 域内，通信代价可以被计算掩盖；一旦跨域（跨机柜、跨节点走 InfiniBand 或以太网），同样的集合通信就从“可掩盖”变成“暴露在关键路径上”。判断标准不是“有没有通信”，而是“通信是否落在解码步的关键路径且消息是否小于带宽时延积”。以 TP 组内每步一次 All-Reduce 为例，单步通信时间近似</p>\n<div class=\"formula\">$$T_{comm}\\approx \\frac{2(N-1)}{N}\\cdot\\frac{M}{B}+L$$</div>\n<p>其中 M 为参与归约的消息字节数、B 为有效带宽、L 为单跳时延、N 为 rank 数。当 M 小（解码阶段每 token 的激活量远小于预填阶段）时，L 主导，此时 TP 扩到 8 与扩到 16 的收益差异被时延吃掉；当 M 大（预填阶段长上下文的一次前向），B 主导，NVLink 5 的高带宽才真正兑现。推理系统的代价因此分档：解码步的 TP 宽度受时延限制，预填步的 TP 宽度受带宽限制，两者不该用同一套切分参数。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-35\">三十五 · All-to-All 与 EP：驱逐与路由的耦合点</h3>\n<p>EP 下 MoE 层的每个 token 要被路由到持有对应专家的 rank，形成 All-to-All。代码模型的 MoE 变体在仓库级长上下文里，token 分布随文件类型与语言结构偏移，热门专家所在 rank 的 KV 与激活显存压力更大，驱逐打分若不感知这种不均衡，就会在热门 rank 上反复触发逐出与重算。工程手段是把 EP 组的显存预算按专家热度做非均匀配额，让 S(b) 的预算约束从全局单一阈值变成 per-rank 阈值；代价是打分器要额外维护热度统计，且配额调整本身引入滞后。具体例子：一个多语言仓库的补全请求里，Python 与 C++ 混合上下文使某几个专家 rank 的驻留块数远超均值，若仍按全局预算逐出，这些 rank 会先丢掉跨文件类型定义块，后续补全对这些符号的引用全部落空，重算 token 数上升。All-to-All 的另一个代价是它不可与解码步完全重叠：路由结果决定下一层输入，属于硬依赖，因此 EP 宽度越大，解码步的暴露时延越明显。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-36\">三十六 · NIXL 传输与分离式预填/解码的边界</h3>\n<p>分离式预填/解码把预填集群与解码集群拆开，KV 需要从预填侧搬到解码侧，NIXL 承担这段点对点传输。对驱逐策略而言，这是一次语义变化：被逐出的块如果在远端预填侧仍有副本，重算可以退化为“重新传输”而非“重新计算”，代价从算力换成带宽与传输时延。判断何时值得这样做，取决于重算一个块的浮点工作量与传输该块 KV 字节数的比值：当块较长、算力紧张而链路有余量时，传输优于重算；当链路拥塞或块很短时，重算更快。系统代价体现在解码集群的显存上——传输过来的块要占用本地 KV 预算，等于把驱逐压力从预填侧转移到解码侧。具体例子：一个长会话 agent 在两次工具调用之间停顿，预填侧保留了上一轮的全部块，解码侧预算不足以全量驻留，此时按 S(b) 保留高引用块、其余按需从预填侧拉取，比在解码侧全量重算更省算力，但拉取时延会体现在首 token 延迟分位上，需要监控侧区分“命中本地”“远端拉取”“本地重算”三类来源。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-37\">三十七 · 通信成为瓶颈的判据</h3>\n<p>把上述几条收敛成可操作的判据：其一，看关键路径——预填阶段的集合通信可被计算掩盖，解码阶段的集合通信不可，因此 TP/EP 的宽度选择要按阶段分开定；其二，看消息尺度——小于带宽时延积的消息由时延主导，扩大并行度只增加同步点数量而不提升有效带宽；其三，看驱逐是否引入跨 rank 分歧——任何导致部分 rank 重算而其余 rank 等待的驱逐，等价于在关键路径上插入一次非对称同步，其代价高于驱逐本身节省的显存；其四，看域边界——NVLink 域内的 All-to-All 与跨域传输是两种量级的代价，NIXL 拉取应尽量落在域内。工程判断上，驱逐策略与并行拓扑必须联合调参：在 TP 组内把保留集合做成组级一致，在 EP 组内按热度做非均匀配额，在分离式部署里把“远端可拉取”作为 S(b) 的一个附加项而非独立机制。监控侧除命中率与重算 token 数外，应单独记录集合通信在解码步中的暴露时间占比，这一项与首 token 延迟分位共同决定并行宽度是否已经越过通信瓶颈的门槛。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-38\">三十八 · 驱逐决策与并行切分的耦合边界：通信何时压过命中收益</h3>\n\n<p>上下文感知驱逐在单卡或纯DP拓扑下是一笔干净的账：省下的KV字节直接换成并发或更长上下文。一旦把同一份分块KV索引放到TP/EP/PP混合切分的部署里，这笔账就不再成立——驱逐改变的不只是显存占用，还改变了集合通信的参与形状。TP组内每层都要做All-Reduce，被逐出的块若恰好落在某个rank的本地分片上，重算时该rank必须重新走一遍预填的激活路径，而TP组其余rank只能空等这一轮集合通信完成。也就是说，一次驱逐引发的重算代价不是按token线性摊到全组，而是以组内最慢rank的重算时间为下界，被All-Reduce的同步语义放大。分块索引与依赖图必须记录每个块在各并行维上的归属，否则打分器会把“本地已逐出、远端仍驻留”的块误判为可复用，命中后触发跨rank的KV补齐传输，这类补齐在NVLink 5上虽带宽充裕，但延迟远高于本地TMEM/SMEM访问。</p>\n\n<p>把通信代价写进打分函数是必要的修正。原打分只含复用、依赖、频次与逐出成本，可在并行部署下追加一项跨rank重算惩罚：</p>\n\n<div class=\"formula\">$$S'(b)=S(b)-\\varepsilon\\cdot\\frac{T_{\\text{recomp}}(b)}{B_{\\text{link}}}\\cdot\\mathbb{1}[\\text{block}(b)\\notin\\text{local shard}]$$</div>\n\n<p>其中分子是重算该块所需传输的激活或KV字节，分母是链路有效带宽，指示函数标记块是否跨分片。工程含义很直接：当块的重算传输量相对链路带宽足够小，跨rank逐出仍划算；当块位于EP的专家分片、重算需要All-to-All拉取专家输出时，惩罚项会迅速把该块推回保留集。EP场景尤其危险——MoE的All-to-All本身已是带宽敏感操作，驱逐导致的重算会在同一批内叠加一次额外的token路由，使All-to-All的通信量与解码流量争抢同一条NVLink 5链路。PP则把问题变成流水线气泡：某stage逐出块后重算拉长了自己的前向时间，下游stage的微批被迫等待，气泡沿流水线累积，首token延迟分位直接恶化。</p>\n\n<p>通信成为瓶颈的判据可以落到一个比值上：设单批解码的计算时间为<span>T</span><sub>comp</sub>，集合通信时间为<span>T</span><sub>comm</sub>，驱逐带来的重算命中收益为<span>H</span>（以节省的KV字节或增加的并发槽位计）。当<span>T</span><sub>comm</sub>已经接近或超过<span>T</span><sub>comp</sub>时，任何引入额外同步点的驱逐都是负收益——因为重算把原本可以异步重叠的通信变成了串行等待。下表给出四种拓扑下驱逐策略的适用边界，均为定性判断，材料未给出具体档位数字。</p>\n\n<table class=\"mini\"><thead><tr><th>并行形态</th><th>驱逐的主要代价</th><th>策略边界</th></tr></thead><tbody><tr><td>纯DP</td><td>仅本地显存与重算算力</td><td>打分器可激进逐出，收益最直接</td></tr><tr><td>TP</td><td>组内All-Reduce同步等待最慢rank重算</td><td>逐出须整组一致，禁止单rank局部逐出</td></tr><tr><td>EP</td><td>重算叠加All-to-All路由流量</td><td>专家分片块加高惩罚项，优先保留</td></tr><tr><td>PP</td><td>重算拉长stage前向，气泡累积</td><td>逐出前移到批调度前仍不够，需按stage预算分配</td></tr></tbody></table>\n\n<p>NIXL这类传输层在这里的角色是双面的：它让分离式预填/解码之间的KV搬运不必走通用RDMA路径，从而降低跨节点重算回填的延迟；但它也把“块在哪里”变成显式的传输决策，驱逐策略必须与NIXL的传输队列协同，否则逐出后集中回填会在预填节点形成传输突发，挤占正常请求的KV下发带宽。失效条件因此很具体：缓存冷启动阶段命中率低，驱逐收益本就有限，此时若再叠加跨rank重算惩罚项，打分器会趋于保守、几乎不逐出，KV预算迅速耗尽并触发OOM或强制降批；反过来，在长会话稳定期若惩罚项权重被在线调参压得过低，系统会退化成近似LRU的激进逐出，跨文件符号被反复重算，首token延迟分位出现锯齿。真正的工程判断是：驱逐策略的收益上界由本地命中率决定，而其代价下界由并行拓扑的同步结构决定，两者相交处才是可部署的工作点——在Blackwell的NVLink 5域内，这个交点通常出现在TP组规模较小、EP专家分片被显式保护的配置上，而非一味追求大TP。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-39\">三十九 · 驱逐决策落在通信拓扑上的边界</h3>\n<p>上下文感知驱逐在单卡或小规模TP下是纯显存问题，一旦KV按TP/EP/PP切分，逐出就变成集合通信问题。分块KV索引必须与各rank的KV分片对齐：TP下每个块的K/V头被切到不同rank，逐出某块意味着所有rank同步释放对应分片，否则后续All-Reduce或All-to-All会读到已失效的偏移。若驱逐在批形成前完成，各rank需在形成批之前交换一次“保留块位图”，这是一次小消息All-Gather，代价随TP度线性增长；若把逐出推迟到解码中途，则会与NCCL集合通信流竞争SM与NVLink带宽，直接放大首token延迟抖动。PP场景更尖锐：逐出发生在某一stage，下游stage的KV预算与索引必须同步更新，否则跨stage的激活与KV引用错位，重算token数反而上升。</p>\n<div class=\"formula\">$$T_{\\text{evict-sync}} \\approx \\frac{B_{\\text{bitmap}}\\cdot (N_{\\text{rank}}-1)}{B_{\\text{NVLink}}} + L_{\\text{NCCL}}$$</div>\n<p>其中位图大小与保留块数成正比，NVLink 5与NVSwitch提供的高带宽使单次同步在微秒量级，但每批都做一次就会摊薄命中收益。工程判断是：把逐出位图合并进已有的批调度元数据交换，避免额外集合通信；当TP度较高或EP引入All-to-All时，逐出频率应随批大小上升而下降，用更粗的保留窗口换取通信次数减少。</p>\n<table class=\"mini\"><thead><tr><th>并行形态</th><th>逐出同步代价</th><th>失效条件</th></tr></thead><tbody><tr><td>TP</td><td>位图All-Gather，随TP度增长</td><td>rank间索引偏移不一致</td></tr><tr><td>PP</td><td>跨stage索引更新，流水气泡</td><td>下游stage预算未同步</td></tr><tr><td>EP/All-to-All</td><td>与专家路由流量争NVLink</td><td>逐出与All-to-All同批叠加</td></tr></tbody></table>\n<p>具体例子：GB200 NVL72上一台整机柜承载多副本TP=8的代码补全服务，逐出位图若每批同步一次，NCCL小消息延迟会进入首token关键路径；把逐出前移到批调度之前并与前缀匹配合并，可让同步落在预填阶段而非解码阶段。NIXL传输在此的角色是跨节点KV块搬移：当某块被判定为高复用但本地已逐出，可从远端副本拉回，代价是NVLink与网络带宽，收益取决于复用概率是否高于搬移成本。边界很清楚：驱逐打分本身消耗CPU与索引内存，跨文件依赖解析在超大仓库下扩展性未给出证据；缓存冷启动阶段命中率低，逐出收益被同步开销抵消，此时应优先预填而非调打分权重。</p>\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-40\">四十 · 精度塌陷：从逐出到数值的连锁反应</h3>\n<p>在上下文感知驱逐的部署里，“精度塌陷”不是指模型权重被破坏，而是指补全质量在长会话中缓慢退化到不可接受，且这种退化往往与KV管理策略耦合。机制上，驱逐把仍被后续请求引用的代码块移出KV索引后，解码阶段必须重算这些块；重算本身不改变数值精度，但若KV以NVFP4/FP8量化存储，逐出—重算—回填的循环会让同一块在不同时刻以不同量化路径重建，块与块之间的数值一致性被打破。打分公式中的复用项与依赖项若权重失衡，系统会倾向于保留“近期被访问但语义已过期”的块，而把跨文件类型定义逐出，补全结果从“编译不过”退化为“编译过但语义错”，这是最难被单元测试捕获的失败形态。</p>\n<p>诊断路径应当把精度塌陷拆成可观测的量：命中率、重算token数、以及重算块占解码总token的比例。设单请求重算比例为 <span class=\"formula\">$$r=\\frac{T_{\\text{recompute}}}{T_{\\text{decode}}}$$</span>，当 <span class=\"formula\">$$r$$</span> 在长会话中单调上升而命中率下降，说明打分器对会话阶段的判断滞后于实际编辑位置。工程代价体现在首token延迟分位上：重算块越多，预填阶段被拉长，P99首token延迟抬升，而吞吐因批内请求等待重算而下降。具体例子：一个agent循环在第N轮修改了跨文件的接口签名，依赖图未及时更新，打分器仍按旧引用关系保留被调用方、逐出调用方，下一轮补全触发大量重算，表现为“每次编辑后第一枪变慢”。定位手段是对逐出决策打点，记录每个被逐出块的分数分量与逐出时刻的会话阶段，回放时对比该块在后续请求中的实际命中情况。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-41\">四十一 · OOM：预算压力下的驱逐时序错位</h3>\n<p>OOM在Blackwell档位上通常不是瞬时超限，而是驱逐与批调度时序错位造成的峰值叠加。机制上，系统在批形成前执行逐出，但批内请求的前缀匹配与打分发生在逐出之前；若多个请求同时命中大量块，索引在打分阶段短暂持有全部候选块的元数据与依赖图边，而KV预算按解码期峰值计算，两者不在同一时刻结算。当批大小与并发配置未按显存档位反推时，这种“元数据峰值”会先于KV峰值触发OOM。B200/B300的HBM容量给了更大预算，但GB200 NVL72的跨节点并行让KV分片分布在多个GPU上，驱逐决策若只在单卡视角做，跨卡引用块的逐出会造成远端重算与通信放大。</p>\n<p>定位OOM要把显存占用按生命周期分段：索引构建、打分、逐出、解码。伪代码思路是给每次驱逐事务加预算检查点——在逐出候选队列确定后、实际释放前，计算 <span class=\"formula\">$$M_{\\text{peak}}=M_{\\text{index}}+M_{\\text{score}}+M_{\\text{kv,retained}}$$</span> 并与档位预算比较，超限则回退到保守窗口。代价是驱逐事务本身增加一次同步检查，轻微抬高批形成延迟，但避免了OOM后的整批重试。具体例子：冷启动阶段缓存命中率低，索引与依赖图尚未稳定，打分器把大量块列为候选却因依赖边持有而无法释放，显存曲线在批形成前出现尖峰；此时应把驱逐前移到索引构建之后、打分之前，用固定窗口兜底。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-42\">四十二 · 批抖动与尾延迟：驱逐打断批内一致性</h3>\n<p>批抖动来自驱逐决策与连续批处理的耦合。机制上，连续批处理允许新请求在解码中途加入，若驱逐发生在解码过程中，批内已有请求的KV块被移出，其后续解码步骤被迫重算，整批的token推进节奏被打断。论文把驱逐前移到批调度之前正是为了消除这种打断，但工程实现中“批调度之前”的边界容易被侵蚀：异步预填、投机解码的草稿阶段、以及分离式预填/解码的跨进程交接，都可能让驱逐在解码窗口内发生。尾延迟的放大系数取决于批内最慢请求的重算量，而非平均值。</p>\n<p>监控上应把逐出次数与批内请求的解码步数关联，计算每批的“逐出—重算”事件率。设批内请求数为 <span class=\"formula\">$$n$$</span>，逐出事件为 <span class=\"formula\">$$e$$</span>，事件率 <span class=\"formula\">$$e/n$$</span> 超过阈值即说明驱逐边界失守。代价是尾延迟P99可能因单次重算抬升数倍于中位数，而吞吐在事件率高的时段反而下降——重算占用了本可用于新请求的算力。具体例子：投机解码的草稿模型在解码中途触发前缀匹配，若匹配逻辑复用了驱逐候选队列，会把本应保留的块标记为可逐出，验证阶段被迫重算，表现为“投机接受率正常但端到端延迟抖动”。定位手段是在驱逐事务上加批上下文标签，禁止在解码窗口内提交逐出。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-43\">四十三 · 静默降级：命中率正常但语义命中失败</h3>\n<p>静默降级是最难监控的失败模式：命中率、重算token数、首token延迟分位都落在SLO内，但补全质量下降。机制上，前缀匹配只验证块的身份与位置，不验证块内容与当前编辑上下文的一致性。当跨文件依赖解析滞后，打分器保留了一个“身份命中但语义已过期”的块——例如函数体被修改但签名未变，块仍被复用，补全基于旧实现生成调用。这种降级不触发重算，因此监控指标全部正常，只有下游编译或测试失败才暴露。依赖图构建的开销与更新频率决定了这种滞后的窗口长度，超大仓库下跨文件解析的可扩展性未给出，滞后可能达到数个会话轮次。</p>\n<p>诊断需要引入语义校验维度：对命中块抽样做轻量一致性检查，比较块内符号的当前版本与索引版本，不一致则降级为未命中并触发重算。伪代码思路是在命中路径上加版本戳比对——<span class=\"formula\">$$\\text{hit}(b)=\\text{prefix\\_match}(b)\\land\\text{version\\_match}(b)$$</span>，版本不匹配的块进入重算队列而非直接复用。代价是每次命中多一次元数据比对，索引内存增加版本字段，但把静默降级转为可观测的重算事件。具体例子：agent循环中一次重构把工具函数从同步改为异步，调用方块被保留复用，补全生成同步调用，编译通过但运行时挂起；版本戳比对会在下一轮把调用方块判为过期，重算后恢复正确语义。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-44\">四十四 · 监控面与回滚：把打分权重当作可回退配置</h3>\n<p>监控面应覆盖四个层次：缓存层（命中率、冷启动命中率、逐出次数）、计算层（重算token数、重算占比、批内事件率）、延迟层（首token延迟分位、端到端延迟分位）、语义层（版本戳不匹配率、抽样一致性失败率）。打分权重 <span class=\"formula\">$$\\alpha,\\beta,\\gamma,\\delta$$</span> 属于部署期在线调参，依据线上命中率与延迟分位反馈更新，材料未给出调参周期与稳定性保证，因此必须把权重配置当作可回滚的运行时参数而非编译期常量。回滚机制上，权重更新应走灰度：新权重先在部分请求流上生效，对比命中率与重算占比，若语义层指标恶化则自动回退到上一组权重。</p>\n<p>工程判断在于：驱逐策略的收益依赖前缀缓存命中质量，冷启动阶段收益有限，需与预填策略协同评估。代价是监控本身引入打点开销与索引版本字段的显存占用，在KV预算紧张时可能挤占可保留块数。具体例子：一次权重调整把复用频次项调高，命中率上升但版本戳不匹配率同步上升，语义层监控触发回滚，避免了静默降级扩散到整个会话池。回滚的粒度应是单打分项而非整组权重，以便定位是哪一类信号导致了退化。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-45\">四十五 · 失效边界：打分收益被自身开销吃掉的那一刻</h3>\n<p>这套方案最容易被误读成“加一层打分就白赚命中率”。实际边界在于：打分器本身要在请求进入时遍历分块KV索引、解析跨文件引用边、判定当前编辑位置属于会话哪一阶段，这些工作全部落在CPU侧与索引查询路径上，发生在首token之前。设单请求分块数为 <span class=\"inline\">n</span>、单块打分代价为 <span class=\"inline\">c<sub>s</sub></span>、索引查询代价为 <span class=\"inline\">c<sub>i</sub></span>，则打分引入的固定前置开销为 <span class=\"inline\">T<sub>score</sub>=n·(c<sub>s</sub>+c<sub>i</sub>)</span>；只有当它换回的重算节省 <span class=\"inline\">T<sub>recompute</sub>=m·t<sub>tok</sub></span>（<span class=\"inline\">m</span> 为被正确保留、免于重算的token数）大于该开销时，净收益才为正。仓库级补全里 <span class=\"inline\">n</span> 随仓库规模上升，而 <span class=\"inline\">m</span> 取决于前缀缓存命中质量——冷启动阶段命中率低，<span class=\"inline\">m</span> 接近零，打分就是纯亏损。工程判断是：把打分限制在“索引已热、依赖图已建”的稳态会话上，冷启动请求走LRU或固定窗口直通路径，不做逐块打分。</p>\n<p>第二类失效是批抖动与尾延迟。逐出被前移到批调度之前是硬约束，一旦某条路径在解码中途触发逐出，批内其他请求的decode步会被重算插入打断，表现为首token延迟分位之外的decode间隔抖动，监控上不易归因。诊断手段是把逐出次数与逐出发生的阶段位点一起打点：若逐出事件出现在解码窗口内，即为策略实现缺陷而非策略本身问题。第三类是静默降级——打分权重在线调整时，若反馈信号只看命中率不看首token延迟分位，权重会向“多保留、少逐出”漂移，KV预算被缓慢吃满直至OOM；这种漂移不报错，只表现为并发上限悄悄下降。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>可观测信号</th><th>定位手段</th><th>回滚动作</th></tr></thead><tbody><tr><td>精度塌陷（量化KV+驱逐叠加）</td><td>补全质量抽样下降、重算块与原块数值偏差</td><td>固定种子对比命中块与重算块输出</td><td>关闭KV量化或退回FP8</td></tr><tr><td>OOM</td><td>KV预算占用率持续爬升、逐出次数趋零</td><td>查权重漂移与保留窗口</td><td>冻结在线调参、强制按分数逐出</td></tr><tr><td>批抖动</td><td>decode间隔分位异常、逐出事件落在解码窗口</td><td>逐出位点打点</td><td>逐出严格前移，禁用中途逐出</td></tr><tr><td>尾延迟</td><td>首token延迟P99与命中率背离</td><td>拆分打分开销与重算开销</td><td>大仓库请求降级为直通</td></tr><tr><td>静默降级</td><td>并发上限缓慢下降、命中率虚高</td><td>命中率与重算token数联合看</td><td>回退上一版权重与保留窗口</td></tr></tbody></table>\n<p>监控口径必须成对：命中率单独看会被“保留过多低价值块”刷高，必须与重算token数、逐出次数、首token延迟分位联读；打分权重在线调整的闭环若缺少延迟分位这一项，就会退化成容量吞噬器。回滚设计上，权重与保留窗口应版本化并可原子切换，切换后清空依赖图缓存重建，避免新旧打分口径混用导致索引与分数不一致。与NVFP4/FP8量化KV结合时，精度塌陷的诊断要区分“量化误差”与“错误逐出后重算路径差异”，前者在固定输入下稳定复现，后者随会话阶段变化——这也是把逐出决策与批调度耦合、并在批形成前完成的另一层理由：让重算发生在可复现的边界上，而不是解码中途。</p>\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-46\">四十六 · 口径先于数字：这篇论文能给出什么、不能给出什么</h3>\n<p>读这篇驱逐论文的基准章节，第一件事不是看它比 LRU 快多少，而是确认它的证据链断在哪里。材料明确：没有数据集名称与规模、没有硬件档位、没有批大小与并发配置、没有量化方案、没有吞吐与延迟数字、没有消融结果。这意味着任何“上下文感知驱逐在 Blackwell 上提升 X%”的说法都不是论文给的，而是读者自己补的。工程上正确的读法是把它当成一个<strong>机制主张</strong>而非<strong>性能主张</strong>：它主张的是“用引用关系、会话阶段、复用频次三类信号替代纯时间序，并把逐出前移到批调度之前”，可核验的部分是这套机制是否自洽、代价是否被计入，而不是收益幅度。</p>\n<p>因此本部分给出的是<strong>评测口径模板</strong>：在 Blackwell 档位上复现这套方法时，必须固定哪些变量、报告哪些指标、哪些跨配置比较在逻辑上不成立。论文的公式 $$S(b)=\\alpha\\cdot R(b)+\\beta\\cdot D(b)+\\gamma\\cdot F(b)-\\delta\\cdot C(b)$$ 中四个系数材料未给取值，也未给归一化方式——这本身就是口径问题：不同仓库的引用图密度差异极大，若 $D(b)$ 未按仓库规模归一，跨仓库的分数不可比，跨仓库的命中率也不可比。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-47\">四十七 · 硬件档位：KV 预算的分母必须先钉死</h3>\n<p>驱逐策略的收益完全由“预算压力”定义。预算宽裕时，任何策略都不逐出，命中率恒为高，策略差异被掩盖；预算紧张时，逐出频繁，打分质量才显现。所以在 B200/B300 单卡与 GB200/GB300 NVL72 机架之间直接比较命中率是无效比较——前者是单卡 HBM 容量约束下的 KV 预算，后者是可跨 NVLink 5 域共享/分片的更大池化空间，两者的“每请求可用 KV 块数”根本不同。</p>\n<p>复现时必须报告的量是每请求 KV 预算 $B_{kv}$ 与上下文块数 $N_b$ 的比值，即压力比：</p>\n<div class=\"formula\">$$\\rho=\\frac{\\sum_{b\\in \\text{ctx}} \\text{size}(b)}{B_{kv}}$$</div>\n<p>$\\rho\\le 1$ 时驱逐不发生，实验无信息量；$\\rho$ 在 1.5–4 区间才是策略真正起作用的区间。材料未给上下文长度分布，因此这个区间只能由部署方按自身请求流实测确定。另一个必须钉死的是量化档位：KV 若走 FP8 或 NVFP4，同样 HBM 下可保留块数成倍增加，$\\rho$ 被压低，驱逐收益随之缩小——把量化前后的命中率放在一张表里比较，等于把两个不同的 $\\rho$ 混为一谈。工程判断是：<strong>先固定 $\\rho$ 与量化档位，再谈策略优劣</strong>；否则测到的是显存容量，不是驱逐算法。</p>\n<p>具体例子：同一仓库级补全请求流，在单卡 B200 上以 BF16 KV 跑出 $\\rho\\approx3$，驱逐频繁；换成 FP8 KV 后 $\\rho\\approx1.5$，逐出次数下降，此时若仍报告“命中率提升”，实际提升来自量化而非打分。这类混淆在缺少硬件档位说明的论文里无法排除。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-48\">四十八 · batch 与并发：驱逐收益与批调度的耦合口径</h3>\n<p>论文的关键机制是“逐出发生在批形成前，避免解码中途打断”。这条机制的性能含义必须用批级指标表达，而不是请求级指标。因为逐出前移的代价是：批形成时多了一次打分与重算规划，这段开销落在<strong>批的排队段</strong>而非解码段；收益则是解码段不再出现因逐出触发的重算停顿，批内其他请求的 TPOT 不被拖尾。</p>\n<p>可核验的口径是分段计时。设批 $B$ 的形成时刻为 $t_0$，解码开始 $t_1$，结束 $t_2$，则排队段 $t_1-t_0$ 应包含打分与逐出规划，解码段 $t_2-t_1$ 应无逐出事件。伪代码思路：</p>\n<div class=\"formula\">$$\\text{plan}(B)\\rightarrow \\{\\text{evict set},\\ \\text{recompute set}\\}\\ \\text{at}\\ t_0;\\quad \\text{decode}(B)\\ \\text{with}\\ \\text{evict\\_count}=0$$</div>\n<p>若监控显示解码段仍出现逐出，说明前移不彻底，机制主张被证伪——这比任何吞吐数字都更有诊断价值。并发维度上，材料未给并发配置，但可以推断：并发升高会同时抬高 $\\rho$ 与批内请求数，逐出的连带影响面变大，打分误差的代价被放大。因此并发扫描应报告“每并发档位的逐出次数/请求数”与“TPOT 的 p99 拖尾”，而不是只报平均吞吐。具体例子：并发从低档升到高档时，若逐出次数线性上升而 TTFT 分位不变，说明打分把重算成本推给了预填段，端到端延迟并未改善——这是典型的指标搬家，不是优化。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-49\">四十九 · 指标族：五个量各自回答不同问题，不可互相替代</h3>\n<p>这套方法至少要报告五类量，每类对应一个独立问题：</p>\n<table class=\"mini\"><thead><tr><th>指标</th><th>回答的问题</th><th>口径要点</th></tr></thead><tbody>\n<tr><td>TTFT 分位（p50/p99）</td><td>命中块复用是否真的省掉了预填</td><td>须区分冷启动与热缓存两段，冷启动阶段命中率低，收益不可外推</td></tr>\n<tr><td>TPOT 分位</td><td>解码段是否被逐出打断</td><td>p99 拖尾是前移是否彻底的直接证据</td></tr>\n<tr><td>命中率</td><td>打分是否选中了后续仍被引用的块</td><td>须按块计而非按 token 计，两者对语义依赖的敏感度不同</td></tr>\n<tr><td>重算 token 数</td><td>逐出决策的错误代价</td><td>与命中率互为镜像，但能暴露“高分块被误逐”的具体量级</td></tr>\n<tr><td>显存占用 / 功耗</td><td>预算是否真的被守住</td><td>依赖图与分块索引本身占内存，须计入</td></tr>\n</tbody></table>\n<p>其中最容易误读的是命中率。按 token 计的命中率会被长块稀释：一个被复用的长函数定义贡献大量 token，掩盖了短小但关键的跨文件符号被逐出的事实。按块计并配合“误逐块中仍被后续请求引用的比例”，才能反映打分器的语义判断质量。功耗维度在 Blackwell 上不可忽略：驱逐带来的重算直接转化为额外的 MMA 与 HBM 带宽消耗，若重算量上升而 TTFT 未降，等于用功耗换了零收益。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-50\">五十 · 哪些提升不可比：四类失效比较</h3>\n<p>第一类，<strong>跨硬件档位的命中率比较</strong>。单卡与 NVL72 的 KV 池化方式不同，$\\rho$ 不同，命中率差异主要来自容量而非算法。第二类，<strong>跨量化档位的延迟比较</strong>。FP8/NVFP4 KV 改变了可保留块数与重算成本，与 BF16 下的驱逐行为不是同一系统。第三类，<strong>跨上下文长度分布的吞吐比较</strong>。材料未给长度分布，若一方请求流以短补全为主，驱逐几乎不触发，吞吐差异会被误读为算法优势。第四类，<strong>与 LRU/固定窗口的比较若未对齐 $\\rho$ 与批大小</strong>，则基线在更宽松预算下运行，比较无效。</p>\n<p>还有一个隐蔽的不可比：打分开销的位置。论文把打分放在请求进入时（前缀匹配后），这段 CPU 与索引查询开销计入 TTFT 的排队段；若基线 LRU 的簿记开销极低，则比较中包含了“用 TTFT 换命中率”的交易，而论文未给这笔交易的定价。工程上应单独报告打分耗时占 TTFT 的比例，超过一定阈值时，命中收益必须显著大于该开销才成立。具体例子：跨文件依赖解析在超大仓库下可能使打分耗时随仓库规模增长，而 LRU 是常数开销——此时“命中率更高”与“TTFT 更低”可以同时不成立，二者并不矛盾。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-51\">五十一 · 复现清单：把不可核验的部分变成可核验的</h3>\n<p>在 Blackwell 上复现这套方法，最小可核验配置应包含：固定量化档位与 $\\rho$ 区间；报告批形成前打分与逐出规划的耗时；报告解码段逐出事件数（应为零）；按块计命中率与误逐率；TTFT 与 TPOT 的 p50/p99 分冷热两段；显存中依赖图与索引的占比。消融维度按材料可推断的三项信号（引用、阶段、复用频次）逐一关闭，观察误逐率而非仅看命中率——因为关闭引用信号后，命中率可能因保留更多近期块而虚高，但跨文件符号的误逐会推高重算 token 数，两个指标背离正是打分器失效的信号。</p>\n<p>最后落在工程判断上：这套方法的收益上界由“缓存冷启动阶段”决定。冷启动时前缀缓存命中质量差，驱逐策略无从发挥，收益接近零；只有当会话进入稳定复用阶段，引用信号才开始产生价值。因此部署时应把驱逐策略与预填策略协同评估，并在监控中把冷启动请求单独分桶——把冷启动与热缓存混在一起算平均命中率，是这套方法最容易被误读的口径。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-52\">五十二 · 基准口径的失效边界：打分开销、冷启动与不可比的“提升”</h3>\n<p>这套驱逐策略的收益不是无条件成立的，它有三个明确的失效面。第一是<strong>打分本身的系统代价</strong>：每个请求进入时要做前缀匹配、遍历分块KV索引、沿依赖图判定跨文件引用是否仍被后续补全需要，这些是CPU侧与索引侧的固定开销，与GPU上的KV预算无关。当仓库规模上升、依赖图边数增长时，单请求打分耗时会挤占调度线程，在批形成前形成串行瓶颈——此时即使命中率上升，端到端TTFT也可能被这段前置处理拖平。判断平衡点的口径应当是“单请求打分耗时 ÷ 批形成周期”，而不是命中率本身。第二是<strong>冷启动阶段</strong>：前缀缓存尚未建立时命中率接近零，驱逐策略退化为无差别逐出，收益窗口不存在，必须与预填策略协同评估，否则测出来的“提升”只是热缓存阶段的切片。第三是<strong>解码中途逐出</strong>：一旦逐出发生在批内某请求解码过程中，同批其他请求的KV布局被打断，重算与回填会污染整批的TPOT，因此前移到批调度之前是硬约束而非优化项。</p>\n<p>口径上，可比的只有同硬件档位、同batch、同并发、同量化方案下的对照。KV若采用NVFP4/FP8，可保留块数上升，驱逐压力下降，命中率曲线整体抬升，此时与FP16 KV下的LRU对比得出的“提升”不可迁移——它混合了量化收益与策略收益。同理，B200单机与GB200 NVL72的显存档位不同，可支撑的并发与上下文长度不同，跨档位的吞吐数字不可比。可核验的口径应固定为：同一仓库请求流、同一SLO阈值、同一KV预算，只切换驱逐策略，并同时报告命中率、重算token数与首token延迟分位。用公式表达预算约束下的保留决策：</p>\n<div class=\"formula\">$$\\text{keep}(b)=\\mathbb{1}\\left[S(b)\\ge \\theta(B)\\right],\\quad \\sum_{b\\in \\text{keep}} \\text{bytes}(b)\\le B$$</div>\n<p>其中阈值θ随剩余预算B动态抬升，预算越紧、门槛越高，被逐出的块越多，重算token数随之上升——这条曲线才是策略的真实代价函数。材料未给出权重取值、归一化方式与调参周期，也未给出硬件档位、batch与并发配置，因此论文主张的“减少重算与TTFT抖动”只能定性表述，无法量化复核。工程判断上，应先在目标档位上测出打分耗时与命中收益的交叉点，再决定是否启用依赖图打分，而不是把语义依赖当作免费收益直接叠加到现有LRU之上。</p>\n<table class=\"mini\"><thead><tr><th>口径项</th><th>可比条件</th><th>不可比情形</th></tr></thead><tbody><tr><td>命中率</td><td>同仓库流、同KV预算</td><td>跨量化方案（FP16 vs NVFP4/FP8）</td></tr><tr><td>TTFT分位</td><td>同batch、同并发、同SLO</td><td>跨硬件档位（B200 vs GB200 NVL72）</td></tr><tr><td>重算token数</td><td>同驱逐策略族对照LRU/固定窗口</td><td>冷启动与热缓存阶段混算</td></tr></tbody></table>\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-53\">五十三 · 迁移到非代码模型：信号源先塌一半</h3>\n<p>这套方案的全部杠杆来自三样东西：文件与符号边界切出的块、跨文件引用构成的依赖图、以及编辑位置能预测“接下来会引用谁”。换到自然语言对话、文档问答、多轮客服，第一样还能勉强保留（段落、章节），第二样直接消失——自然语言没有稳定的符号引用关系，<span class=\"formula\">$$D(b)$$</span> 这一项要么退化为“共现/相似度”这种噪声很大的替代量，要么被迫置零。第三样也弱化：编辑位置在代码里是强信号（光标附近必然高频引用），在对话里“下一句会提到什么”几乎不可预测。于是打分公式 <span class=\"formula\">$$S(b)=\\alpha R(b)+\\beta D(b)+\\gamma F(b)-\\delta C(b)$$</span> 中真正还能站住的只剩 <span class=\"formula\">$$R(b)$$</span>（近期复用频次）和会话阶段项。判断很直接：<strong>非代码领域迁移时，先把 <span class=\"formula\">$$\\beta$$</span> 压到很小甚至归零，把预算让给复用频次与会话阶段，否则依赖项会引入大量假阳性保留，白占 KV 预算。</strong>代价体现在显存上：假阳性保留意味着高分段被无复用价值的块占据，真正会被引用的块反而被逐出，重算 token 数上升，首 token 延迟分位变差。举例：一份 30 页技术文档的问答会话，段落间“引用关系”其实是主题相似，按依赖图打分会把整章都标成高依赖，等于退化成固定窗口。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-54\">五十四 · 迁移到别的代码模型：切块粒度与 tokenizer 必须重标定</h3>\n<p>块是按文件与符号边界切的，这个边界依赖模型的上下文窗口与 tokenizer 的切分行为。换模型（不同上下文长度、不同 BPE 词表）后，同一个函数在不同 tokenizer 下的 token 数差异会直接改变“一个块占多少 KV 预算”，进而改变逐出阈值。工程上要改的不是打分逻辑，而是三处标定：块的最大 token 上限、前缀匹配的最长公共前缀判定、以及重算规划里“一个未命中块重算要多少 token”的估算。伪代码思路是：<em>对每个候选块，用目标模型的 tokenizer 重新计算 len(b)，按 <span class=\"formula\">$$\\text{len}(b)/\\text{budget}$$</span> 归一化后再进入排序</em>，否则跨模型直接复用旧阈值会出现“小块永远保留、大块永远被逐”的偏斜。代价是显存与带宽：块粒度变粗（比如按整个文件切）会让单块 KV 占用上升，前缀命中时的复用收益变大但逐出粒度变粗，一次误逐出就要重算整个文件，首 token 延迟抖动幅度随之放大。例子：同一仓库在 32K 窗口模型上按函数切块合理，换到 128K 窗口模型后若仍按函数切，块数暴涨、索引与依赖图维护开销线性上升，而单块预算占比变小，打分的区分度被稀释。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-55\">五十五 · 与量化 KV 结合时的边界：分数不能替代精度决策</h3>\n<p>把 NVFP4/FP8 量化 KV 引进来会改变这套方案的经济学，但不改变它的决策结构。量化让单位显存能装更多块，等于把预算 <span class=\"formula\">$$\\text{budget}$$</span> 放大，逐出压力下降，打分器的边际收益随之下降——这是收益被稀释的边界。更关键的边界是：<strong>打分器决定“留不留”，量化决定“留的块用多少位存”，两者是正交的，不能用一个分数同时决定。</strong>如果把低分块直接降到低精度而不是逐出，看似省了重算，实际上低精度块在后续被引用时精度损失会传导到补全质量，而这条路径没有监控项覆盖（现有监控只有命中率、重算 token 数、首 token 延迟分位）。工程判断：在量化 KV 档位下，逐出策略应从“激进逐出”转为“分层保留”——高分块全精度、中分块量化保留、低分块逐出，但分层阈值需要按线上命中率反馈重标，材料未给出该阈值。代价是显存带宽：混合精度 KV 让 attention 读取路径出现分支，tcgen05 路径上的 KV 读取不再是单一精度流，带宽利用率与 kernel 效率都要重新测。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-56\">五十六 · 规模上限：依赖图与索引是 O(仓库规模) 的隐性成本</h3>\n<p>方案在服务侧维护分块 KV 索引与依赖图，这两者的构建与更新成本随仓库规模增长，而材料明确未给出超大仓库下的可扩展性证据。规模上限出现在两个位置。其一是依赖图的边数：跨文件引用在万级文件仓库里是稠密图，每次编辑都要更新受影响子图，更新延迟会挤进请求关键路径。其二是前缀匹配：请求进入时先做前缀匹配再打分，匹配本身要对候选块集合做扫描，候选集随并发会话数增长。可推断的规模上限判据是：<em>当单次请求的索引查询与打分耗时接近首 token 延迟 SLO 的余量时，方案失效</em>，因为省下的重算收益被前置开销吃掉。代价是 CPU 与功耗：打分与图维护是 CPU 侧工作，在 GB200 NVL72 这种整机柜部署里，CPU 侧开销会转化为机柜功耗预算的一部分，而 GPU 侧的显存节省未必能等量换算成整柜吞吐提升。例子：单仓库 5000 文件、并发 64 会话时，若每次请求都要遍历全部候选块打分，前置开销可能达到毫秒级，对低延迟补全 SLO 是实质性挤占——这是需要实测的平衡点，材料未给数字。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-57\">五十七 · 不适用的场景：冷启动、短会话、单文件</h3>\n<p>三类场景应直接判定不适用，而不是调参硬上。第一，缓存冷启动阶段：前缀缓存命中率低，驱逐策略没有可保留的高分块，收益趋近于零，此时应把预算让给预填策略而非驱逐策略，材料明确指出冷启动阶段收益未给出、需与预填协同评估。第二，短会话单文件补全：上下文块数少，KV 预算不构成约束，逐出根本不触发，打分器的索引与图维护是纯开销。第三，解码中途需要动态调整上下文的 agent 循环：方案要求逐出严格前移到批调度之前，若 agent 在解码中途才决定丢弃某段上下文，这套机制无法在不打断批内其他请求的前提下执行逐出，只能等下一批形成，实时性受损。判断：<strong>这套方案的适用域是“长会话 + 跨文件 + 预算受限”三者同时成立</strong>，缺一个就该换更简单的 LRU 或固定窗口，把工程复杂度省下来。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-58\">五十八 · 迁移检查清单：改什么、测什么、什么时候放弃</h3>\n<p>把迁移决策落成可执行的检查项，而不是口号。要改的：块切分粒度按目标模型 tokenizer 重标定；依赖项权重 <span class=\"formula\">$$\\beta$$</span> 按领域信号强度重设（代码保留、非代码压低）；逐出阈值按量化 KV 档位分层；索引与图更新移出请求关键路径（异步增量更新）。要测的：前置打分开销占首 token 延迟的比例、命中率与重算 token 数的比值、混合精度 KV 下的带宽利用率、超大仓库下依赖图更新的尾延迟。放弃判据：前置开销吃掉重算收益、或依赖图更新延迟进入 SLO 余量、或冷启动命中率长期低位。一个具体工程判断是：<em>先在单仓库中等规模上测“打分开销 / 节省的重算 token 时间”这个比值，比值小于 1 才值得上生产</em>；材料未给出该比值，因此这是部署期必须自测的门槛，而不是论文能替你回答的问题。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-59\">五十九 · 迁移边界：打分器在什么仓库、什么模型上会失效</h3>\n<p>这套方案的可迁移性不由驱逐算法本身决定，而由“依赖图能否在预算内建准”决定。打分项 <span class=\"formula\">$$S(b)=\\alpha\\cdot R(b)+\\beta\\cdot D(b)+\\gamma\\cdot F(b)-\\delta\\cdot C(b)$$</span> 中，<span class=\"formula\">$$D(b)$$</span> 依赖跨文件符号解析，<span class=\"formula\">$$R(b)$$</span> 依赖会话内复用统计。迁到单文件脚本仓库、无类型标注的动态语言仓库、或符号解析器覆盖不全的代码库时，<span class=\"formula\">$$D(b)$$</span> 退化为噪声，打分等价于带阶段权重的近似 LRU，收益随之消失。反过来，迁到强类型、模块边界清晰、跨文件引用密集的仓库，<span class=\"formula\">$$D(b)$$</span> 的信息量最高，方案最成立。判断标准是依赖图的边密度与解析覆盖率，而非仓库体积。</p>\n<p>迁到别的模型时，要先看该模型的上下文窗口与KV布局是否支持块级索引。若模型使用非分块的位置编码或对前缀连续性有严格要求，块级复用会因位置偏移而失效，命中块无法直接拼接，方案退化为整段重算。迁到非代码领域（长文档问答、多轮客服）时，<span class=\"formula\">$$D(b)$$</span> 没有符号引用可依，需要替换为实体共指或段落引用图，<span class=\"formula\">$$F(b)$$</span> 的会话阶段划分也要重定义；此时打分器的在线调参闭环仍可用，但冷启动期的权重没有先验，命中率爬升慢于代码场景。</p>\n<table class=\"mini\"><thead><tr><th>迁移维度</th><th>成立条件</th><th>失效表现与系统代价</th></tr></thead><tbody><tr><td>仓库结构</td><td>跨文件引用密集、解析覆盖率高</td><td>依赖图退化，打分≈LRU；索引构建占用CPU，命中收益被抵消</td></tr><tr><td>模型KV布局</td><td>支持块级前缀复用与位置连续</td><td>命中块不可拼接，退化为整段重算，首token延迟分位抬升</td></tr><tr><td>领域语义</td><td>存在可解析的引用/共指结构</td><td>打分信号缺失，冷启动期命中率低，驱逐收益有限</td></tr><tr><td>规模</td><td>依赖图构建与打分在批调度前完成</td><td>超大仓库解析超时，逐出决策被迫后移，解码抖动回归</td></tr></tbody></table>\n<p>规模上限落在两处。第一处是依赖图的构建与维护成本：仓库越大、跨文件边越多，索引更新与打分排序占用的CPU时间越长；而逐出必须前移到批调度之前，这段串行开销直接进入请求关键路径，压缩了可用于批形成的窗口，等效于降低并发上限。第二处是重算预算：驱逐越激进，未命中块越多，重算token数上升，预填算力与KV带宽被重算吃掉，在NVFP4/FP8量化KV下可保留块数增加，但重算的算力代价不会因量化而消失。工程判断是：先用命中率与重算token数测出打分开销的盈亏平衡点，再决定是否把依赖图扩展到跨仓库粒度；若打分开销已接近命中节省的预填时间，就应退回按文件粒度的粗打分，把预算留给批调度与预填/解码分离，而不是继续加细依赖图。</p>\n\n<h3 id=\"paper-context-aware-codellm-eviction-for-a-2025-sec-60\">六十 · 迁移边界：依赖图假设、冷启动失效与规模上限</h3>\n<p>这套方案的可迁移性取决于一个前提：请求流中存在可解析的跨块依赖结构。代码领域天然满足——函数调用、类型引用、import 关系都能静态或半静态抽取，依赖图构建有明确边界。迁到自然语言长文档、多轮客服会话或结构化日志分析时，块间依赖退化为弱语义相似度，<span class=\"formula\">$$D(b)$$</span> 项失去可计算的定义，打分退化成\"近期复用频次 + 会话阶段\"两项，与带时间衰减的 LRU 差距收窄。此时应直接放弃依赖项，把预算让给更粗粒度的前缀缓存，而不是硬套三信号加权。判断标准是：能否在请求到达时以低于重算成本的代价算出块间引用，若单次依赖解析的 CPU 时间接近一次短块重算的 GPU 时间，方案不成立。</p>\n<p>失效条件集中在冷启动与阶段切换。缓存为空时命中率接近零，驱逐决策没有可保留对象，打分开销纯属负收益；监控侧应设置命中率门限，低于门限时旁路打分器、退回固定窗口，待索引预热后再启用。会话阶段信号在 agent 循环中尤其脆弱：一次工具调用返回后编辑位置突变，上一阶段的高分块可能整体失效，若保留窗口调整滞后一个批周期，就会把已死块占着预算、把新依赖块挤到重算路径。工程上应把阶段切换做成显式事件而非打分器隐式推断。</p>\n<table class=\"mini\"><thead><tr><th>迁移目标</th><th>需改动</th><th>不适用情形</th></tr></thead><tbody><tr><td>同族代码模型换档</td><td>仅重调权重与保留窗口</td><td>分块边界与符号解析器不兼容</td></tr><tr><td>自然语言长上下文</td><td>删除依赖项，退化为复用+阶段</td><td>无稳定块边界，前缀缓存已足够</td></tr><tr><td>超大仓库</td><td>依赖图分区、增量更新</td><td>全图解析开销超过重算收益</td></tr></tbody></table>\n<p>规模上限由索引与依赖图的维护成本决定，而非 KV 预算。仓库规模增长时依赖图边数超线性上升，跨文件解析与增量更新占用 CPU 与主机内存，这部分开销不随 NVFP4/FP8 量化 KV 而缩小——量化只扩大可保留块数，反而加重索引负担。可迁移的规模上限应表述为：依赖图维护成本占单请求端到端延迟的比例必须低于命中收益带来的首token延迟下降比例，否则方案在更大仓库上净负。这个比例材料未给出，只能在目标仓库上以命中率、重算token数与首token延迟分位三项联测确定拐点。</p>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 138\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"52.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Context-Aware CodeLLM </text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Eviction for AI-a…</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"74.0\" x2=\"271.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 69.5 L 270.0 78.5 L 278.0 74.0 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"74.0\" x2=\"515.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 69.5 L 514.0 78.5 L 522.0 74.0 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"128.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2025 · arXiv preprint</text></svg><figcaption><b>家谱</b> · Context-Aware CodeLLM E… 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>仓库级代码补全请求流（材料未给出具体数据集名称与规模）</td></tr><tr><td>基线</td><td>LRU 驱逐、固定窗口驱逐</td></tr><tr><td>主要结果</td><td>材料未给出可核验的吞吐、命中率或延迟数字；论文主张上下文感知驱逐在长会话与…</td></tr><tr><td>消融</td><td>材料未给出消融实验细节；可推断的消融维度为打分项（引用、阶段、复用频次）的…</td></tr><tr><td>局限</td><td>材料未给出硬件档位、批大小与并发配置，无法核验SLO达成情况；依赖图构建与…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-context-aware-codellm-eviction-for-a-2025 · 共 9 个片段</p>\n";break;}}})();
